  # Other parameters / 其他参数  run_jackstraw = FALSE,             # Whether to run JackStraw analysis / 是否运行JackStraw分析  jackstraw_replicates = 100,        # JackStraw replicates / JackStraw重采样次数  cumulative_variance_threshold = 0.90, # Cumulative variance threshold / 累积方差贡献率阈值  small_cluster_threshold = 50,      # Small cluster threshold / 小聚类阈值  max_clusters_silhouette = 20,      # Max clusters for silhouette / 轮廓系数计算的最大聚类数  marker_min_pct = 0.1,              # Minimum pct for marker detection / marker最小表达比例  annotation_marker_top_n = 4,       # Top markers per cell type for annotation dot plot / 注释气泡图每类细胞显示前几个marker
  # Nebula plot parameters / 星云图参数  nebula_coord_extend_group = 2,     # Group plot coordinate extension / 分组图坐标轴扩展范围  nebula_coord_extend_single = 5,    # Single plot coordinate extension / 单一图坐标轴扩展范围  nebula_density_n_group = 250,      # Group plot density resolution / 分组图密度计算分辨率  nebula_density_n_single = 300,     # Single plot density resolution / 单一图密度计算分辨率  nebula_density_adjust_group = 1.2, # Group plot density smoothing / 分组图密度平滑度  nebula_density_adjust_single = 1.5,# Single plot density smoothing / 单一图密度平滑度  nebula_point_size = 0.005,         # Star point size / 星点大小  nebula_point_alpha = 0.2,          # Star point transparency / 星点透明度  nebula_point_color = "#FFFFFFAA",  # Star point color / 星点颜色
