# ==============================================================================# 02.1 Helper Functions / 辅助函数# ==============================================================================
detect_elbow_pc <- function(stdev_values) {  stdev_values <- as.numeric(stdev_values)  stdev_values <- stdev_values[is.finite(stdev_values)]  n_dims <- length(stdev_values)
  if (n_dims <= 2) {    return(max(1, n_dims))  }
  x_vals <- seq_len(n_dims)  x_scaled <- (x_vals - min(x_vals)) / (max(x_vals) - min(x_vals))
  y_range <- range(stdev_values, na.rm = TRUE)  if (!is.finite(y_range[1]) || !is.finite(y_range[2]) || diff(y_range) == 0) {    return(max(2, min(n_dims, 5)))  }  y_scaled <- (stdev_values - y_range[1]) / diff(y_range)
  line_values <- y_scaled[1] + (y_scaled[n_dims] - y_scaled[1]) * x_scaled  distances <- line_values - y_scaled  elbow_pc <- which.max(distances)
  max(1, min(elbow_pc, n_dims))}
get_pc_selection_info <- function(stdev_values,                                  selection_mode = "auto",                                  cumulative_threshold = 0.90,                                  manual_pc = 13,                                  auto_min = 5,                                  auto_buffer = 5) {  stdev_values <- as.numeric(stdev_values)  stdev_values <- stdev_values[is.finite(stdev_values)]  available_pcs <- length(stdev_values)
  if (available_pcs < 1) {    stop("No valid PCA standard deviations available for PC selection")  }
  variance_values <- stdev_values^2  total_variance <- sum(variance_values)  if (!is.finite(total_variance) || total_variance <= 0) {    stop("Invalid PCA variance: unable to determine principal components")  }
  variance_ratio <- variance_values / total_variance  cumulative_variance <- cumsum(variance_ratio)  cumulative_pc <- which(cumulative_variance >= cumulative_threshold)[1]  if (is.na(cumulative_pc)) {    cumulative_pc <- available_pcs  }
  elbow_pc <- detect_elbow_pc(stdev_values)  min_pc_use <- min(max(2, auto_min), available_pcs)
  if (identical(selection_mode, "manual")) {    pc_use <- min(max(2, manual_pc), available_pcs)  } else {    candidate_pc <- max(elbow_pc, min(cumulative_pc, elbow_pc + auto_buffer))    pc_use <- min(max(candidate_pc, min_pc_use), available_pcs)  }
  list(    pc_use = pc_use,    available_pcs = available_pcs,    cumulative_pc = cumulative_pc,    elbow_pc = elbow_pc,    variance_ratio = variance_ratio,    cumulative_variance = cumulative_variance  )}
map_ensembl_to_symbol <- function(gene_ids) {  gene_ids <- trimws(as.character(gene_ids))  gene_ids_no_version <- sub("\\.[0-9]+$", "", gene_ids)  unique_ids <- unique(gene_ids_no_version[nzchar(gene_ids_no_version)])
  if (length(unique_ids) == 0) {    return(data.frame(      Ensembl_ID = gene_ids,      Gene = gene_ids,      stringsAsFactors = FALSE    ))  }
  symbol_map <- rep(NA_character_, length(unique_ids))  names(symbol_map) <- unique_ids  annotation_sources <- character(0)
  if (requireNamespace("EnsDb.Hsapiens.v86", quietly = TRUE)) {    ensdb <- get("EnsDb.Hsapiens.v86", envir = asNamespace("EnsDb.Hsapiens.v86"))    ensdb_map <- AnnotationDbi::mapIds(      x = ensdb,      keys = unique_ids,      keytype = "GENEID",      column = "SYMBOL",      multiVals = "first"    )    symbol_map[names(ensdb_map)] <- unname(ensdb_map)    annotation_sources <- c(annotation_sources, "EnsDb.Hsapiens.v86")  }
  missing_ids <- names(symbol_map)[is.na(symbol_map) | !nzchar(symbol_map)]  if (length(missing_ids) > 0 && requireNamespace("org.Hs.eg.db", quietly = TRUE)) {    orgdb_map <- AnnotationDbi::mapIds(      x = org.Hs.eg.db::org.Hs.eg.db,      keys = missing_ids,      keytype = "ENSEMBL",      column = "SYMBOL",      multiVals = "first"    )    filled_ids <- names(orgdb_map)[!is.na(orgdb_map) & nzchar(orgdb_map)]    symbol_map[filled_ids] <- unname(orgdb_map[filled_ids])    annotation_sources <- c(annotation_sources, "org.Hs.eg.db")  }
  if (length(annotation_sources) == 0) {    stop("Gene ID conversion requires EnsDb.Hsapiens.v86 or org.Hs.eg.db.")  }
  mapped_symbols <- unname(symbol_map[gene_ids_no_version])  mapped_symbols[is.na(mapped_symbols) | !nzchar(mapped_symbols)] <- gene_ids[    is.na(mapped_symbols) | !nzchar(mapped_symbols)  ]
  result <- data.frame(    Ensembl_ID = gene_ids,    Gene = mapped_symbols,    stringsAsFactors = FALSE  )  attr(result, "annotation_source") <- paste(annotation_sources, collapse = " + ")  result}
convert_ensembl_matrix_to_symbols <- function(count_matrix) {  original_genes <- rownames(count_matrix)
  if (is.null(original_genes) || length(original_genes) == 0) {    stop("Input matrix has no gene row names.")  }
  if (!any(grepl("^ENSG", original_genes))) {    message("Gene row names do not look like Ensembl IDs; skipping gene ID conversion.")    return(list(      matrix = count_matrix,      mapping = data.frame(        Ensembl_ID = original_genes,        Gene = original_genes,        stringsAsFactors = FALSE      )    ))  }
  gene_mapping <- map_ensembl_to_symbol(original_genes)  annotation_source <- attr(gene_mapping, "annotation_source")  mapped_genes <- gene_mapping$Gene  valid_genes <- !is.na(mapped_genes) & nzchar(mapped_genes)  count_matrix <- count_matrix[valid_genes, , drop = FALSE]  gene_mapping <- gene_mapping[valid_genes, , drop = FALSE]  attr(gene_mapping, "annotation_source") <- annotation_source  mapped_genes <- gene_mapping$Gene
  if (anyDuplicated(mapped_genes) > 0) {    message(sprintf(      "Collapsing %d duplicated gene symbols by summing counts.",      sum(duplicated(mapped_genes))    ))    grouping_matrix <- Matrix::sparseMatrix(      i = seq_along(mapped_genes),      j = as.integer(factor(mapped_genes, levels = unique(mapped_genes))),      x = 1,      dims = c(length(mapped_genes), length(unique(mapped_genes))),      dimnames = list(NULL, unique(mapped_genes))    )    count_matrix <- Matrix::t(grouping_matrix) %*% count_matrix    rownames(count_matrix) <- colnames(grouping_matrix)  } else {    rownames(count_matrix) <- mapped_genes  }
  list(matrix = count_matrix, mapping = gene_mapping)}
estimate_doublet_rate <- function(capture_cells) {  doublet_rate_table <- data.frame(    cells = c(500, 1000, 2000, 3000, 4000, 5000, 6000, 7000, 8000, 9000, 10000),    rate  = c(0.004, 0.008, 0.016, 0.023, 0.031, 0.039, 0.046, 0.054, 0.061, 0.069, 0.076)  )
  capture_cells <- as.numeric(capture_cells)  if (!is.finite(capture_cells) || capture_cells <= 0) {    return(0.004)  }
  min_cells <- min(doublet_rate_table$cells)  max_cells <- max(doublet_rate_table$cells)
  if (capture_cells <= max_cells) {    estimated_rate <- approx(      x = doublet_rate_table$cells,      y = doublet_rate_table$rate,      xout = max(capture_cells, min_cells),      rule = 2    )$y  } else {    last_idx <- nrow(doublet_rate_table)    prev_idx <- last_idx - 1    slope <- (doublet_rate_table$rate[last_idx] - doublet_rate_table$rate[prev_idx]) /      (doublet_rate_table$cells[last_idx] - doublet_rate_table$cells[prev_idx])    estimated_rate <- doublet_rate_table$rate[last_idx] +      (capture_cells - doublet_rate_table$cells[last_idx]) * slope  }
  min(max(estimated_rate, 0.004), 0.20)}
get_counts_matrix <- function(seurat_obj, assay = "RNA", cells = NULL) {  counts_mat <- tryCatch(    GetAssayData(seurat_obj, assay = assay, layer = "counts"),    error = function(e) GetAssayData(seurat_obj, assay = assay, slot = "counts")  )
  if (!is.null(cells)) {    counts_mat <- counts_mat[, cells, drop = FALSE]  }
  counts_mat}
create_discrete_palette <- function(group_levels) {  group_levels <- as.character(group_levels)  n_groups <- length(group_levels)
  if (n_groups == 0) {    return(character(0))  }
  base_palette <- c(    "#E41A1C", "#377EB8", "#4DAF4A", "#FF7F00", "#984EA3",    "#A65628", "#F781BF", "#00BFC4", "#FFD700", "#0000FF",    "#33A02C", "#FB9A99", "#1F78B4", "#B2DF8A", "#FDBF6F",    "#CAB2D6", "#6A3D9A", "#B15928", "#17BECF", "#D62728"  )
  if (n_groups <= length(base_palette)) {    palette_values <- base_palette[seq_len(n_groups)]  } else {    palette_values <- grDevices::colorRampPalette(base_palette)(n_groups)  }
  names(palette_values) <- group_levels  palette_values}
save_interactive_3d_umap <- function(seurat_obj,                                     group_by,                                     output_file,                                     plot_title,                                     color_title) {  if (!"umap3d" %in% names(seurat_obj@reductions)) {    stop("3D UMAP reduction 'umap3d' not found. Please run RunUMAP(..., n.components = 3).")  }
  umap3d_coords <- as.data.frame(Embeddings(seurat_obj, "umap3d"))  if (ncol(umap3d_coords) < 3) {    stop("3D UMAP reduction must contain at least 3 dimensions.")  }  umap3d_coords <- umap3d_coords[, 1:3, drop = FALSE]  colnames(umap3d_coords) <- c("UMAP3D_1", "UMAP3D_2", "UMAP3D_3")  umap3d_coords$Cell_ID <- rownames(umap3d_coords)
  if (identical(group_by, "ident")) {    group_values <- as.character(Idents(seurat_obj))  } else if (group_by %in% colnames(seurat_obj@meta.data)) {    group_values <- as.character(seurat_obj@meta.data[[group_by]])  } else {    stop(sprintf("Metadata column '%s' not found for 3D UMAP coloring.", group_by))  }  group_values[is.na(group_values) | group_values == ""] <- "Unknown"  group_levels <- sort(unique(group_values))  umap3d_coords$Group_Label <- factor(group_values, levels = group_levels)
  cluster_values <- if ("seurat_clusters" %in% colnames(seurat_obj@meta.data)) {    as.character(seurat_obj@meta.data$seurat_clusters)  } else {    rep("NA", nrow(umap3d_coords))  }  sample_values <- if ("sample_id" %in% colnames(seurat_obj@meta.data)) {    as.character(seurat_obj@meta.data$sample_id)  } else {    rep("NA", nrow(umap3d_coords))  }  type_values <- if ("Type" %in% colnames(seurat_obj@meta.data)) {    as.character(seurat_obj@meta.data$Type)  } else {    rep("NA", nrow(umap3d_coords))  }
  umap3d_coords$Hover_Text <- paste0(    "Cell: ", umap3d_coords$Cell_ID,    "<br>", color_title, ": ", as.character(umap3d_coords$Group_Label),    "<br>Cluster: ", cluster_values,    "<br>Sample: ", sample_values,    "<br>Group: ", type_values  )
  color_values <- create_discrete_palette(group_levels)  plot_3d <- plotly::plot_ly(    data = umap3d_coords,    x = ~UMAP3D_1,    y = ~UMAP3D_2,    z = ~UMAP3D_3,    color = ~Group_Label,    colors = color_values,    text = ~Hover_Text,    hoverinfo = "text",    type = "scatter3d",    mode = "markers",    marker = list(size = 2, opacity = 0.75)  ) %>%    plotly::layout(      title = list(text = plot_title),      legend = list(title = list(text = color_title)),      scene = list(        xaxis = list(title = "UMAP3D_1"),        yaxis = list(title = "UMAP3D_2"),        zaxis = list(title = "UMAP3D_3")      )    )
  output_dir <- dirname(output_file)  if (!dir.exists(output_dir)) {    dir.create(output_dir, recursive = TRUE)  }
  tryCatch({    htmlwidgets::saveWidget(      widget = plot_3d,      file = output_file,      selfcontained = TRUE,      title = plot_title    )  }, error = function(e) {    message("Self-contained HTML export failed, saving with external widget library folder: ", e$message)    htmlwidgets::saveWidget(      widget = plot_3d,      file = output_file,      selfcontained = FALSE,      title = plot_title    )  })
  message(sprintf("Saved interactive 3D UMAP page: %s", output_file))  invisible(output_file)}
get_expression_data_matrix <- function(seurat_obj, assay = "RNA") {  tryCatch(    GetAssayData(seurat_obj, assay = assay, layer = "data"),    error = function(e) {      GetAssayData(seurat_obj, assay = assay, slot = "data")    }  )}
generate_cluster_maincelltype_plots <- function(seurat_obj,                                                genes,                                                mapping_file,                                                output_dir,                                                assay = "RNA") {  if (!file.exists(mapping_file)) {    stop("Cluster to cell type mapping file not found / 未找到聚类与细胞类型映射文件：", mapping_file)  }  if (!dir.exists(output_dir)) {    dir.create(output_dir, recursive = TRUE)  }  if (!"seurat_clusters" %in% colnames(seurat_obj@meta.data)) {    stop("Metadata column 'seurat_clusters' not found / 未找到seurat_clusters元数据列")  }
  cluster_ann <- read.csv(    mapping_file,    stringsAsFactors = FALSE,    check.names = FALSE,    fileEncoding = "UTF-8"  )  if (ncol(cluster_ann) < 2) {    stop("Cluster mapping file must contain at least two columns / 聚类映射文件至少需要两列")  }  colnames(cluster_ann)[1:2] <- c("Cluster", "CellType")  cluster_ann <- cluster_ann[!is.na(cluster_ann$Cluster) & nzchar(cluster_ann$Cluster), , drop = FALSE]  cluster_ann$Cluster <- as.character(cluster_ann$Cluster)  cluster_ann$CellType <- as.character(cluster_ann$CellType)
  cluster_order_numeric <- suppressWarnings(as.numeric(cluster_ann$Cluster))  if (all(!is.na(cluster_order_numeric))) {    cluster_ann <- cluster_ann[order(cluster_order_numeric), , drop = FALSE]  } else {    cluster_ann <- cluster_ann[order(cluster_ann$Cluster), , drop = FALSE]  }  cluster_ann <- cluster_ann[!duplicated(cluster_ann$Cluster), , drop = FALSE]
  cluster_levels <- cluster_ann$Cluster  cluster_labels <- paste0("c-", cluster_ann$Cluster, "\n", cluster_ann$CellType)  names(cluster_labels) <- cluster_levels  cluster_colors <- colorRampPalette(RColorBrewer::brewer.pal(12, "Set3"))(length(cluster_levels))  names(cluster_colors) <- cluster_levels
  expr_mat <- get_expression_data_matrix(seurat_obj, assay = assay)  available_genes <- genes[genes %in% rownames(expr_mat)]  missing_genes <- setdiff(genes, available_genes)
  if (length(missing_genes) > 0) {    message(      "These genes are missing in the expression matrix / 以下基因不在表达矩阵中，将跳过：",      paste(missing_genes, collapse = ", ")    )  }  if (length(available_genes) == 0) {    stop("No genes from gene.txt were found in the expression matrix / gene.txt中的基因均未在表达矩阵中找到")  }
  cluster_values <- as.character(seurat_obj@meta.data$seurat_clusters)  mapped_celltypes <- cluster_ann$CellType[match(cluster_values, cluster_ann$Cluster)]  mapped_celltypes[is.na(mapped_celltypes) | !nzchar(mapped_celltypes)] <-    paste0("Cluster_", cluster_values[is.na(mapped_celltypes) | !nzchar(mapped_celltypes)])
  expr_long_list <- lapply(available_genes, function(gene_name) {    data.frame(      Cell = colnames(seurat_obj),      Cluster = cluster_values,      CellType = mapped_celltypes,      Gene = gene_name,      Gene_Expression = as.numeric(expr_mat[gene_name, ]),      stringsAsFactors = FALSE    )  })  expr_long_df <- dplyr::bind_rows(expr_long_list)  expr_long_df <- expr_long_df[expr_long_df$Cluster %in% cluster_levels, , drop = FALSE]
  if (nrow(expr_long_df) == 0) {    stop("No cells matched the cluster mapping file / 没有细胞匹配到聚类注释映射")  }
  expr_long_df$Cluster <- factor(expr_long_df$Cluster, levels = cluster_levels)  expr_long_df$ClusterLabel <- factor(    expr_long_df$Cluster,    levels = cluster_levels,    labels = cluster_labels  )
  bubble_df <- expr_long_df %>%    dplyr::group_by(Cluster, Gene) %>%    dplyr::summarise(      avg_expr = mean(Gene_Expression, na.rm = TRUE),      pct_pos = mean(Gene_Expression > 0, na.rm = TRUE) * 100,      .groups = "drop"    )
  bubble_df$Gene <- factor(bubble_df$Gene, levels = unique(available_genes))  bubble_df$Y <- bubble_df$Gene
  p_dot <- ggplot(bubble_df, aes(x = Cluster, y = Y, size = pct_pos, color = avg_expr)) +    geom_point() +    scale_x_discrete(labels = cluster_labels, expand = expansion(add = 0.5)) +    scale_y_discrete(expand = expansion(add = 0.5)) +    scale_size(range = c(5, 20), name = "Percent Positive") +    scale_color_gradientn(colors = c("blue", "white", "red"), name = "Avg Expression") +    theme_classic(base_size = 16) +    theme(      axis.text.x = element_text(angle = 45, hjust = 1, vjust = 1, face = "bold"),      axis.text.y = element_text(face = "bold", size = 16),      axis.title.y = element_blank(),      axis.title.x = element_blank(),      plot.title = element_text(face = "bold", hjust = 0.5),      plot.margin = ggplot2::margin(t = 5, r = 5, b = 5, l = 40, unit = "pt")    ) +    labs(title = "Gene Expression DotPlot by Cluster (Main Cell Type)")
  dotplot_pdf <- file.path(output_dir, "AllGenes_DotPlot_byCluster_withMainCellType.pdf")  pdf(dotplot_pdf, width = 15, height = 6 + 0.7 * length(unique(available_genes)))  print(p_dot)  dev.off()  message("Generated dot plot / 已生成气泡图：", dotplot_pdf)
  for (gene_name in available_genes) {    expr_df <- expr_long_df[expr_long_df$Gene == gene_name, , drop = FALSE]
    p_vln <- ggplot(expr_df, aes(x = ClusterLabel, y = Gene_Expression, fill = Cluster)) +      geom_violin(scale = "width", trim = TRUE, adjust = 1, width = 0.9) +      stat_summary(fun = median, geom = "point", shape = 23, size = 2, fill = "white", color = "black") +      scale_fill_manual(values = cluster_colors) +      theme_classic(base_size = 16) +      theme(        axis.text.x = element_text(angle = 45, hjust = 1, vjust = 1, face = "bold", size = 12),        axis.text.y = element_text(face = "bold"),        axis.title.x = element_blank(),        axis.title.y = element_text(face = "bold"),        strip.text = element_text(face = "bold", size = 16),        legend.position = "none",        plot.title = element_text(face = "bold", hjust = 0.5),        plot.margin = ggplot2::margin(t = 5, r = 5, b = 60, l = 40, unit = "pt")      ) +      labs(y = "Expression", title = paste0(gene_name, " Expression by Cluster (Main Cell Type)"))
    vln_pdf <- file.path(output_dir, paste0(gene_name, "_VlnPlot_byCluster_withMainCellType.pdf"))    pdf(vln_pdf, width = 14, height = 7)    print(p_vln)    dev.off()    message("Generated violin plot / 已生成小提琴图：", vln_pdf)  }}
get_count_data_matrix <- function(seurat_obj, assay = "RNA") {  tryCatch(    GetAssayData(seurat_obj, assay = assay, layer = "counts"),    error = function(e) {      GetAssayData(seurat_obj, assay = assay, slot = "counts")    }  )}
write_utf8_lines <- function(lines, output_file) {  con <- file(output_file, open = "w", encoding = "UTF-8")  on.exit(close(con), add = TRUE)  writeLines(lines, con = con, useBytes = TRUE)}
generate_aucell_analysis <- function(seurat_obj,                                     gmt_file,                                     output_dir,                                     assay = "RNA",                                     random_seed = 1234,                                     auc_max_rank_fraction = 0.05,                                     max_plot_gene_sets = 12) {  if (!dir.exists(output_dir)) {    dir.create(output_dir, recursive = TRUE)  }  if (!"umap" %in% names(seurat_obj@reductions)) {    stop("UMAP reduction not found / 未找到UMAP降维结果，无法绘制AUCell UMAP图")  }  if (!file.exists(gmt_file)) {    stop("GMT file not found / 未找到GMT文件：", gmt_file)  }
  required_meta <- c("cell_type", "Type", "seurat_clusters")  missing_meta <- setdiff(required_meta, colnames(seurat_obj@meta.data))  if (length(missing_meta) > 0) {    stop("Missing required metadata columns / 缺少必要元数据列：", paste(missing_meta, collapse = ", "))  }
  open_pdf_safely <- function(file_path, width, height) {    pdf_dir <- dirname(file_path)    pdf_ext <- tools::file_ext(file_path)    pdf_base <- tools::file_path_sans_ext(basename(file_path))    final_path <- file_path    pdf_opened <- tryCatch({      pdf(final_path, width = width, height = height)      TRUE    }, error = function(e) FALSE)
    if (!pdf_opened) {      timestamp <- format(Sys.time(), "%Y%m%d_%H%M%S")      final_path <- file.path(pdf_dir, paste0(pdf_base, "_", timestamp, ".", pdf_ext))      pdf(final_path, width = width, height = height)      message("原PDF可能正在被打开或占用，已另存为：", final_path)    }
    final_path  }
  count_mat <- get_count_data_matrix(seurat_obj, assay = assay)  if (!inherits(count_mat, "dgCMatrix")) {    count_mat <- methods::as(count_mat, "dgCMatrix")  }
  read_gmt_gene_sets <- function(file_path, gene_universe = NULL) {    gmt_lines <- readLines(file_path, warn = FALSE, encoding = "UTF-8")    gmt_lines <- gmt_lines[nzchar(trimws(gmt_lines))]    if (length(gmt_lines) == 0) {      stop("GMT file is empty / GMT文件为空：", file_path)    }
    gene_sets <- list()    gene_format <- character(0)
    for (line_idx in seq_along(gmt_lines)) {      fields <- strsplit(gmt_lines[[line_idx]], "\t", fixed = TRUE)[[1]]      fields <- trimws(fields)      fields <- fields[nzchar(fields)]
      if (length(fields) < 2) {        next      }
      gene_set_name <- fields[[1]]      second_field <- if (length(fields) >= 2) fields[[2]] else ""      second_is_description <- grepl("^(na|n/a|null|none)$", second_field, ignore.case = TRUE) ||        grepl("://|^www\\.", second_field) ||        grepl("\\s", second_field)
      gene_start_idx <- 2L      if (length(fields) >= 3) {        if (!is.null(gene_universe)) {          overlap_from_second <- sum(fields[2:length(fields)] %in% gene_universe)          overlap_from_third <- sum(fields[3:length(fields)] %in% gene_universe)          second_in_universe <- second_field %in% gene_universe
          if (overlap_from_third > overlap_from_second ||              (!second_in_universe && overlap_from_third == overlap_from_second && second_is_description)) {            gene_start_idx <- 3L          }        } else if (second_is_description) {          gene_start_idx <- 3L        }      }
      genes <- unique(fields[gene_start_idx:length(fields)])      genes <- genes[nzchar(genes)]      if (length(genes) == 0) {        next      }
      gene_sets[[gene_set_name]] <- genes      gene_format[[gene_set_name]] <- if (gene_start_idx == 3L) {        "standard_gmt"      } else {        "name_plus_genes"      }    }
    if (length(gene_sets) == 0) {      stop("No valid gene sets were parsed from GMT / 未能从GMT文件解析到有效基因集：", file_path)    }
    list(      gene_sets = gene_sets,      gene_format = gene_format    )  }
  parsed_gmt <- read_gmt_gene_sets(gmt_file, gene_universe = rownames(count_mat))  gene_sets_all <- parsed_gmt$gene_sets  gene_format <- parsed_gmt$gene_format  gene_sets_subset <- lapply(gene_sets_all, function(gs) intersect(gs, rownames(count_mat)))  gene_set_sizes <- vapply(gene_sets_subset, length, integer(1))  valid_idx <- which(gene_set_sizes > 0)  if (length(valid_idx) == 0) {    stop("No gene sets from GMT matched the expression matrix / GMT中的基因集与表达矩阵没有交集")  }
  gene_sets_subset <- gene_sets_subset[valid_idx]  gene_set_sizes <- vapply(gene_sets_subset, length, integer(1))  gene_set_names <- names(gene_sets_subset)  gene_sets_list <- gene_sets_subset  names(gene_sets_list) <- gene_set_names
  gmt_summary_df <- data.frame(    GeneSet = gene_set_names,    GMT_Format = unname(gene_format[gene_set_names]),    Genes_In_Input = as.integer(vapply(gene_sets_all[gene_set_names], length, integer(1))),    Genes_In_Matrix = as.integer(gene_set_sizes),    stringsAsFactors = FALSE  )  gmt_summary_df <- gmt_summary_df %>%    dplyr::arrange(dplyr::desc(Genes_In_Matrix), GeneSet)
  write.csv(    gmt_summary_df,    file = file.path(output_dir, "01_AUCell_GeneSet_Summary.csv"),    row.names = FALSE,    fileEncoding = "UTF-8"  )
  auc_max_rank <- max(1L, floor(nrow(count_mat) * auc_max_rank_fraction))
  open_pdf_safely(file.path(output_dir, "02_AUCell_BuildRankings_Stats.pdf"), width = 8, height = 6)  cells_rankings <- AUCell_buildRankings(    exprMat = count_mat,    plotStats = TRUE,    verbose = FALSE  )  dev.off()
  cells_auc <- AUCell_calcAUC(    geneSets = gene_sets_list,    rankings = cells_rankings,    aucMaxRank = auc_max_rank,    nCores = 1  )
  auc_matrix <- AUCell::getAUC(cells_auc)  if (nrow(auc_matrix) == 0) {    stop("AUCell result is empty / AUCell结果为空")  }
  set.seed(random_seed)  open_pdf_safely(file.path(output_dir, "03_AUCell_Threshold_Histograms.pdf"), width = 10, height = 8)  cells_assignment <- AUCell_exploreThresholds(    cells_auc,    plotHist = TRUE,    assign = TRUE,    nCores = 1  )  dev.off()
  selected_thresholds <- getThresholdSelected(cells_assignment)  if (length(selected_thresholds) == 0) {    stop("No selected AUCell thresholds were returned / AUCell未返回自动选择阈值")  }
  threshold_table <- dplyr::bind_rows(lapply(names(cells_assignment), function(gs_name) {    assignment_info <- cells_assignment[[gs_name]]    gs_thresholds <- as.data.frame(assignment_info$aucThr$thresholds, stringsAsFactors = FALSE)    gs_thresholds$Method <- rownames(gs_thresholds)    rownames(gs_thresholds) <- NULL    gs_thresholds <- gs_thresholds[, c("Method", setdiff(colnames(gs_thresholds), "Method")), drop = FALSE]    gs_thresholds$GeneSet <- gs_name    gs_thresholds$Selected_Threshold <- as.numeric(selected_thresholds[[gs_name]])    gs_thresholds$Comment <- assignment_info$aucThr$comment    gs_thresholds  }))  threshold_table <- threshold_table[, c("GeneSet", "Method", setdiff(colnames(threshold_table), c("GeneSet", "Method"))), drop = FALSE]
  sample_values <- if ("sample_id" %in% colnames(seurat_obj@meta.data)) {    as.character(seurat_obj@meta.data$sample_id)  } else {    rep(NA_character_, ncol(seurat_obj))  }
  metadata_df <- data.frame(    Cell_ID = colnames(seurat_obj),    Sample = sample_values,    Group = as.character(seurat_obj@meta.data$Type),    Cluster = as.character(seurat_obj@meta.data$seurat_clusters),    Cell_Type = as.character(seurat_obj@meta.data$cell_type),    stringsAsFactors = FALSE  )
  auc_matrix_df <- as.data.frame(t(auc_matrix))  auc_matrix_df$Cell_ID <- rownames(auc_matrix_df)  rownames(auc_matrix_df) <- NULL  aucell_wide_df <- dplyr::left_join(metadata_df, auc_matrix_df, by = "Cell_ID")
  aucell_long_df <- aucell_wide_df %>%    tidyr::pivot_longer(      cols = dplyr::all_of(rownames(auc_matrix)),      names_to = "GeneSet",      values_to = "AUC_Score"    ) %>%    dplyr::mutate(      Selected_Threshold = as.numeric(selected_thresholds[GeneSet]),      Active = AUC_Score > Selected_Threshold    )
  group_summary <- aucell_long_df %>%    dplyr::group_by(GeneSet, Group) %>%    dplyr::summarise(      Cells = dplyr::n(),      Mean_AUC = mean(AUC_Score, na.rm = TRUE),      Median_AUC = median(AUC_Score, na.rm = TRUE),      Active_Cells = sum(Active, na.rm = TRUE),      Active_Fraction = mean(Active, na.rm = TRUE) * 100,      .groups = "drop"    )
  cell_type_summary <- aucell_long_df %>%    dplyr::group_by(GeneSet, Cell_Type, Group) %>%    dplyr::summarise(      Cells = dplyr::n(),      Mean_AUC = mean(AUC_Score, na.rm = TRUE),      Median_AUC = median(AUC_Score, na.rm = TRUE),      Active_Cells = sum(Active, na.rm = TRUE),      Active_Fraction = mean(Active, na.rm = TRUE) * 100,      .groups = "drop"    )
  cluster_summary <- aucell_long_df %>%    dplyr::group_by(GeneSet, Cluster, Cell_Type, Group) %>%    dplyr::summarise(      Cells = dplyr::n(),      Mean_AUC = mean(AUC_Score, na.rm = TRUE),      Median_AUC = median(AUC_Score, na.rm = TRUE),      Active_Cells = sum(Active, na.rm = TRUE),      Active_Fraction = mean(Active, na.rm = TRUE) * 100,      .groups = "drop"    )
  assigned_cells_df <- dplyr::bind_rows(lapply(names(cells_assignment), function(gs_name) {    assigned_cells <- cells_assignment[[gs_name]]$assignment    if (length(assigned_cells) == 0) {      return(data.frame(GeneSet = character(0), Cell_ID = character(0), stringsAsFactors = FALSE))    }    data.frame(      GeneSet = gs_name,      Cell_ID = assigned_cells,      stringsAsFactors = FALSE    )  }))
  write.csv(    aucell_long_df,    file = file.path(output_dir, "04_AUCell_Cell_Scores_Long.csv"),    row.names = FALSE,    fileEncoding = "UTF-8"  )  write.csv(    aucell_wide_df,    file = file.path(output_dir, "04_AUCell_Cell_Scores_Wide.csv"),    row.names = FALSE,    fileEncoding = "UTF-8"  )  write.csv(    threshold_table,    file = file.path(output_dir, "05_AUCell_Thresholds.csv"),    row.names = FALSE,    fileEncoding = "UTF-8"  )  write.csv(    group_summary,    file = file.path(output_dir, "06_AUCell_Group_Summary.csv"),    row.names = FALSE,    fileEncoding = "UTF-8"  )  write.csv(    cell_type_summary,    file = file.path(output_dir, "07_AUCell_CellType_Summary.csv"),    row.names = FALSE,    fileEncoding = "UTF-8"  )  write.csv(    cluster_summary,    file = file.path(output_dir, "08_AUCell_Cluster_Summary.csv"),    row.names = FALSE,    fileEncoding = "UTF-8"  )  write.csv(    assigned_cells_df,    file = file.path(output_dir, "09_AUCell_Assigned_Cells.csv"),    row.names = FALSE,    fileEncoding = "UTF-8"  )  saveRDS(cells_auc, file = file.path(output_dir, "10_AUCell_AUC_Object.rds"))  saveRDS(cells_assignment, file = file.path(output_dir, "11_AUCell_Assignment_Object.rds"))
  plot_gene_sets <- group_summary %>%    dplyr::group_by(GeneSet) %>%    dplyr::summarise(Max_Active_Fraction = max(Active_Fraction, na.rm = TRUE), .groups = "drop") %>%    dplyr::arrange(dplyr::desc(Max_Active_Fraction), GeneSet) %>%    dplyr::slice_head(n = max_plot_gene_sets) %>%    dplyr::pull(GeneSet)
  if (length(plot_gene_sets) == 0) {    stop("No gene sets available for AUCell plotting / 没有可用于AUCell绘图的基因集")  }
  plot_obj <- seurat_obj  score_col_names <- paste0("AUCell_", make.names(plot_gene_sets), "_Score")  names(score_col_names) <- plot_gene_sets
  for (gs_name in plot_gene_sets) {    score_col <- score_col_names[[gs_name]]    gs_scores <- auc_matrix[gs_name, colnames(plot_obj)]    gs_scores <- as.numeric(gs_scores)    plot_obj[[score_col]] <- gs_scores  }
  umap_coords <- as.data.frame(Embeddings(plot_obj, "umap"))  colnames(umap_coords)[1:2] <- c("UMAP_1", "UMAP_2")  umap_coords$Cell_ID <- rownames(umap_coords)  umap_coords$Cell_Type <- as.character(plot_obj@meta.data$cell_type)
  umap_label_df <- umap_coords %>%    dplyr::group_by(Cell_Type) %>%    dplyr::summarise(      UMAP_1 = median(UMAP_1, na.rm = TRUE),      UMAP_2 = median(UMAP_2, na.rm = TRUE),      .groups = "drop"    )
  aucell_feature_colors <- viridis::magma(256, begin = 0, end = 0.98)
  build_aucell_umap_plot <- function(gs_name, show_legend = TRUE) {    score_col <- score_col_names[[gs_name]]    gs_scores <- as.numeric(plot_obj@meta.data[umap_coords$Cell_ID, score_col])    gs_max_score <- suppressWarnings(max(gs_scores, na.rm = TRUE))    if (!is.finite(gs_max_score) || gs_max_score <= 0) {      gs_max_score <- 1    }    gs_display_max <- suppressWarnings(as.numeric(stats::quantile(      gs_scores,      probs = 0.99,      na.rm = TRUE,      names = FALSE    )))    if (!is.finite(gs_display_max) || gs_display_max <= 0) {      gs_display_max <- gs_max_score    }    gs_display_max <- min(gs_display_max, gs_max_score)    if (!is.finite(gs_display_max) || gs_display_max <= 0) {      gs_display_max <- 1    }
    legend_breaks <- seq(0, gs_display_max, length.out = 4)    legend_breaks <- round(legend_breaks, 3)    legend_labels <- format(legend_breaks, trim = TRUE, scientific = FALSE, nsmall = 3)    plot_df <- umap_coords    plot_df$auc_score <- gs_scores    plot_df <- plot_df[order(plot_df$auc_score), , drop = FALSE]
    suppressMessages(      suppressWarnings(        ggplot(plot_df, aes(x = UMAP_1, y = UMAP_2, color = auc_score)) +          geom_point(size = 1.2) +          scale_color_gradientn(            colors = aucell_feature_colors,            limits = c(0, gs_display_max),            breaks = legend_breaks,            labels = legend_labels,            name = "auc_score",            oob = scales::squish          ) +          geom_text_repel(            data = umap_label_df,            mapping = aes(x = UMAP_1, y = UMAP_2, label = Cell_Type),            inherit.aes = FALSE,            size = 3,            fontface = "bold",            color = "black",            box.padding = 0.4,            point.padding = 0.2,            segment.color = "grey40",            max.overlaps = Inf          ) +          ggtitle(gs_name) +          theme_minimal() +          theme(            panel.grid.major = element_blank(),            panel.grid.minor = element_blank(),            axis.line = element_line(color = "black"),            axis.text = element_text(color = "black"),            axis.title = element_text(color = "black", face = "bold"),            plot.title = element_text(size = 12, face = "bold", hjust = 0.5),            legend.title = element_text(face = "bold"),            legend.position = if (show_legend) "right" else "none"          ) +          labs(x = "UMAP_1", y = "UMAP_2")      )    )  }
  aucell_score_plots <- lapply(plot_gene_sets, build_aucell_umap_plot)
  open_pdf_safely(    file.path(output_dir, "12_AUCell_UMAP_Score.pdf"),    width = 6 * min(3, length(plot_gene_sets)),    height = 5 * ceiling(length(plot_gene_sets) / 3)  )  print(patchwork::wrap_plots(aucell_score_plots, ncol = min(3, length(plot_gene_sets))))  dev.off()
  invisible(    list(      auc = cells_auc,      assignment = cells_assignment,      per_cell_scores = aucell_long_df,      selected_thresholds = selected_thresholds,      plotted_gene_sets = plot_gene_sets    )  )}
