# 自动检测分组前缀# 支持格式: control./Control./control_/Control_ 为对照组#           Disease./Disease_/Treat./Treat_ 为疾病组ctrl_dot <- any(grepl("^control\\.", cell_names, ignore.case = TRUE))ctrl_under <- any(grepl("^control_", cell_names, ignore.case = TRUE))dis_dot <- any(grepl("^Disease\\.", cell_names, ignore.case = TRUE))dis_under <- any(grepl("^Disease_", cell_names, ignore.case = TRUE))treat_dot <- any(grepl("^Treat\\.", cell_names, ignore.case = TRUE))treat_under <- any(grepl("^Treat_", cell_names, ignore.case = TRUE))
if (ctrl_dot) {  control_pattern <- "^control\\."  message("Detected control group prefix: control.")} else if (ctrl_under) {  control_pattern <- "^control_"  message("Detected control group prefix: control_")} else {  control_pattern <- NULL}
if (dis_dot) {  disease_pattern <- "^Disease\\."  message("Detected disease group prefix: Disease.")} else if (dis_under) {  disease_pattern <- "^Disease_"  message("Detected disease group prefix: Disease_")} else if (treat_dot) {  disease_pattern <- "^Treat\\."  message("Detected disease group prefix: Treat.")} else if (treat_under) {  disease_pattern <- "^Treat_"  message("Detected disease group prefix: Treat_")} else {  disease_pattern <- NULL}
if (is.null(control_pattern) && is.null(disease_pattern)) {  stop("ERROR: No group prefixes found in cell names!\n",       "Supported control prefixes: control. / control_ / Control. / Control_\n",       "Supported disease prefixes: Disease. / Disease_ / Treat. / Treat_")}
control_cells_found <- !is.null(control_pattern) && any(grepl(control_pattern, cell_names, ignore.case = TRUE))disease_cells_found <- !is.null(disease_pattern) && any(grepl(disease_pattern, cell_names, ignore.case = TRUE))
if (control_cells_found) {  message(sprintf("Detected control group cells: %d",                  sum(grepl(control_pattern, cell_names, ignore.case = TRUE))))}if (disease_cells_found) {  message(sprintf("Detected disease group cells: %d",                  sum(grepl(disease_pattern, cell_names, ignore.case = TRUE))))}
if (!control_cells_found) {  stop("ERROR: No control group cells found!")}if (!disease_cells_found) {  stop("ERROR: No Disease/Treat group cells found!")}
