# Add initial sample and group metadatacell_names_seurat <- colnames(Peripheral_Blood_Mononuclear_Cells)extract_sample_id <- function(cell_names) {  sample_ids <- rep(NA_character_, length(cell_names))
  # Preferred format used by the GSE157783 matrix:  # Control.GSM4774936_AAAC... or Disease.GSM4774931_AAAC...  dot_gsm <- grepl("^(control|disease|treat)\\.GSM[0-9]+_", cell_names, ignore.case = TRUE)  sample_ids[dot_gsm] <- sub(    "^((control|disease|treat)\\.GSM[0-9]+)_.*$",    "\\1",    cell_names[dot_gsm],    ignore.case = TRUE  )
  # Also support Control_GSM4774936_AAAC... style names.  under_gsm <- is.na(sample_ids) &    grepl("^(control|disease|treat)_GSM[0-9]+_", cell_names, ignore.case = TRUE)  sample_ids[under_gsm] <- sub(    "^((control|disease|treat)_GSM[0-9]+)_.*$",    "\\1",    cell_names[under_gsm],    ignore.case = TRUE  )
  # Fallback for older inputs where the final underscore-delimited part is the barcode.  fallback <- is.na(sample_ids)  sample_ids[fallback] <- sub("_[^_]+$", "", cell_names[fallback])
  sample_ids}
