get_adaptive_decontx_threshold <- function(contam_values,                                           min_threshold = decontX_min_threshold,                                           max_threshold = decontX_max_threshold) {  q1 <- as.numeric(stats::quantile(contam_values, 0.25, na.rm = TRUE, names = FALSE))  q3 <- as.numeric(stats::quantile(contam_values, 0.75, na.rm = TRUE, names = FALSE))  iqr_value <- q3 - q1  adaptive_threshold <- q3 + 1.5 * iqr_value  adaptive_threshold <- max(adaptive_threshold, min_threshold)  adaptive_threshold <- min(adaptive_threshold, max_threshold)  adaptive_threshold}
