run_scdblfinder_fallback <- function(seurat_obj, sample_name) {  sce_obj <- SingleCellExperiment::SingleCellExperiment(    assays = list(counts = GetAssayData(seurat_obj, layer = "counts"))  )  set.seed(123)  sce_obj <- scDblFinder::scDblFinder(sce_obj, samples = rep(sample_name, ncol(sce_obj)))  raw_class <- as.character(SummarizedExperiment::colData(sce_obj)$scDblFinder.class)  ifelse(raw_class == "doublet", "Doublet", "Singlet")}
