  message(sprintf("  样本 %s: %d 细胞", samp, nCells_sub))
  if (nCells_sub < 100) {    if (scDblFinder_available) {      message(sprintf("  样本 %s 细胞数不足100，改用 scDblFinder", samp))      classifications <- run_scdblfinder_fallback(sub_obj, samp)      method_used <- "scDblFinder"    } else {      message(sprintf("  样本 %s 细胞数不足100，当前环境无 scDblFinder，标记为 Not_Evaluated 并保留", samp))      classifications <- rep("Not_Evaluated", nCells_sub)      method_used <- "Not_Evaluated"    }  } else {    classifications <- tryCatch({      sub_obj <- NormalizeData(sub_obj, verbose = FALSE)      sub_obj <- FindVariableFeatures(        sub_obj,        selection.method = "vst",        nfeatures = min(analysis_params$n_variable_features, nrow(sub_obj)),        verbose = FALSE      )      sub_obj <- ScaleData(sub_obj, verbose = FALSE)
      max_pca_possible <- min(        analysis_params$n_pcs,        ncol(sub_obj) - 1,        nrow(sub_obj) - 1,        length(VariableFeatures(sub_obj))      )      if (is.na(max_pca_possible) || max_pca_possible < 5) {        stop("可用于DoubletFinder的主成分数不足5")      }
      sub_obj <- RunPCA(sub_obj, npcs = max_pca_possible, verbose = FALSE)      doublet_pc_info <- get_pc_selection_info(        stdev_values = sub_obj[["pca"]]@stdev,        selection_mode = analysis_params$pc_selection_mode,        cumulative_threshold = analysis_params$cumulative_variance_threshold,        manual_pc = analysis_params$pcSelect,        auto_min = 5,        auto_buffer = analysis_params$pc_auto_buffer      )      doublet_dims <- seq_len(doublet_pc_info$pc_use)      if (length(doublet_dims) < 5) {        stop("参数扫描所需主成分不足5")      }      message(sprintf(        "  样本 %s 自动选择DoubletFinder维度: %d PCs (elbow=%d, cumulative=%d)",        samp, doublet_pc_info$pc_use, doublet_pc_info$elbow_pc, doublet_pc_info$cumulative_pc      ))
      sub_obj <- RunUMAP(sub_obj, dims = doublet_dims, verbose = FALSE)      sub_obj <- FindNeighbors(sub_obj, dims = doublet_dims, verbose = FALSE)      sub_obj <- FindClusters(sub_obj, resolution = 0.5, verbose = FALSE)
      sweep.res.list <- paramSweep(sub_obj, PCs = doublet_dims, sct = FALSE)      sweep.stats <- summarizeSweep(sweep.res.list, GT = FALSE)      bcmvn <- find.pK(sweep.stats)      valid_pk_idx <- which(is.finite(bcmvn$BCmetric))      if (length(valid_pk_idx) == 0) {        pK_value <- 0.08        message(sprintf("  样本 %s 未找到有效pK，回退使用默认值 %.2f", samp, pK_value))      } else {        best_pk_idx <- valid_pk_idx[which.max(bcmvn$BCmetric[valid_pk_idx])]        pK_value <- as.numeric(as.character(bcmvn$pK[best_pk_idx]))      }      message(sprintf("  样本 %s 最优pK值: %s", samp, pK_value))
      message(sprintf("  样本 %s 用于估算双细胞率的原始捕获细胞数: %d", samp, capture_cells_for_rate))      doublet_rate <- estimate_doublet_rate(capture_cells_for_rate)      if (capture_cells_for_rate > 10000) {        message(sprintf("  样本 %s 捕获细胞数超过10000，使用线性外推估算双细胞率", samp))      }      message(sprintf("  样本 %s 预估双细胞率: %.2f%%", samp, doublet_rate * 100))
      homotypic.prop <- modelHomotypic(sub_obj$seurat_clusters)      expected_doublets_input <- max(round(doublet_rate * capture_cells_for_rate), 1)      nExp_poi <- min(expected_doublets_input, max(nCells_sub - 1, 1))      expected_doublets_adj <- max(round(nExp_poi * (1 - homotypic.prop)), 1)      nExp_poi.adj <- min(expected_doublets_adj, max(nCells_sub - 1, 1))      message(sprintf("  样本 %s 期望双细胞数: 原始估计=%d, 输入DoubletFinder=%d, 同型校正后=%d",                      samp, expected_doublets_input, nExp_poi, nExp_poi.adj))
      sub_obj <- doubletFinder(        sub_obj,        PCs = doublet_dims,        pN = 0.25,        pK = pK_value,        nExp = nExp_poi.adj,        sct = FALSE      )      df_col <- grep("^DF.classifications", colnames(sub_obj@meta.data), value = TRUE)[1]      as.character(sub_obj@meta.data[[df_col]])    }, error = function(e) {      if (scDblFinder_available) {        message(sprintf("  样本 %s 的 DoubletFinder 失败，回退到 scDblFinder: %s", samp, e$message))        method_used <<- "scDblFinder_fallback"        run_scdblfinder_fallback(Peripheral_Blood_Mononuclear_Cells[, cells_idx], samp)      } else {        message(sprintf("  样本 %s 的 DoubletFinder 失败，标记为 Not_Evaluated: %s", samp, e$message))        method_used <<- "Not_Evaluated"        rep("Not_Evaluated", nCells_sub)      }    })  }
  n_doublet <- sum(classifications == "Doublet")  n_singlet <- sum(classifications == "Singlet")  n_not_evaluated <- sum(classifications == "Not_Evaluated")  message(sprintf("  样本 %s: 检测到 %d 双细胞, %d 单细胞, %d 未评估",                  samp, n_doublet, n_singlet, n_not_evaluated))
  names(classifications) <- colnames(sub_obj)  doublet_classification_all <- c(doublet_classification_all, classifications)  cells_to_keep_all <- c(cells_to_keep_all, colnames(sub_obj)[classifications != "Doublet"])
