# Save batch correction QC plots before/after Harmonysave_batch_correction_qc_plot <- function(seurat_obj, reduction_name, file_name,                                          stage_label_cn, stage_label_en) {  if (!reduction_name %in% Reductions(seurat_obj)) {    warning(sprintf("Reduction %s not found; skipping batch correction QC plot", reduction_name))    return(invisible(NULL))  }
  plot_object <- seurat_obj  plot_list <- list()  output_file <- file.path(output_dirs$quality_control, file_name)
  if (analysis_params$harmony_group %in% colnames(plot_object@meta.data)) {    plot_list[[length(plot_list) + 1]] <- DimPlot(      object = plot_object,      reduction = reduction_name,      group.by = analysis_params$harmony_group,      pt.size = 0.4    ) +      ggtitle(sprintf("%s\nBy sample", stage_label_en)) +      NoGrid()  }
  inferred_group_col <- NULL  if ("Type" %in% colnames(plot_object@meta.data)) {    inferred_group_col <- "Type"  } else {    inferred_group <- rep(NA_character_, ncol(plot_object))    if (!is.null(control_pattern)) {      inferred_group[grepl(control_pattern, colnames(plot_object), ignore.case = TRUE)] <- "control"    }    if (!is.null(disease_pattern)) {      inferred_group[grepl(disease_pattern, colnames(plot_object), ignore.case = TRUE)] <- "Disease"    }    if (any(!is.na(inferred_group))) {      plot_object$BatchQC_Group <- inferred_group      inferred_group_col <- "BatchQC_Group"    }  }
  if (!is.null(inferred_group_col) &&      inferred_group_col %in% colnames(plot_object@meta.data) &&      any(!is.na(plot_object@meta.data[[inferred_group_col]]))) {    plot_list[[length(plot_list) + 1]] <- DimPlot(      object = plot_object,      reduction = reduction_name,      group.by = inferred_group_col,      pt.size = 0.4    ) +      ggtitle(sprintf("%s\nBy group", stage_label_en)) +      NoGrid()  }
  if (length(plot_list) == 0) {    warning(sprintf("No metadata available for batch correction QC plot: %s", output_file))    return(invisible(NULL))  }
  pdf(file = output_file, width = 7 * min(length(plot_list), 2), height = 6)  print(wrap_plots(plot_list, ncol = min(length(plot_list), 2)))  dev.off()
  message(sprintf("Batch correction QC plot saved: %s", output_file))  message(sprintf("去批次前后质控图已保存: %s", output_file))}
