  # Get cells  tryCatch({    con_cells <- colnames(Peripheral_Blood_Mononuclear_Cells)[Peripheral_Blood_Mononuclear_Cells$group == con_name]    dis_cells <- colnames(Peripheral_Blood_Mononuclear_Cells)[Peripheral_Blood_Mononuclear_Cells$group == dis_name]  }, error = function(e) {    message(sprintf("Error getting cells for %s: %s", cellName, e$message))    con_cells <<- character(0)    dis_cells <<- character(0)  })
  if (length(con_cells) >= 3 & length(dis_cells) >= 3) {    message(sprintf("Analyzing %s - control: %d cells, Disease: %d cells",                    cellName, length(con_cells), length(dis_cells)))    message(sprintf("分析 %s - 对照组: %d 细胞, 疾病组: %d 细胞",                    cellName, length(con_cells), length(dis_cells)))
    tryCatch({      pbmc_markers <- FindMarkers(        Peripheral_Blood_Mononuclear_Cells,        ident.1 = dis_cells,        ident.2 = con_cells,        group.by = 'group',        logfc.threshold = 0.1      )
      sig_markers_group <- pbmc_markers[        (abs(pbmc_markers$avg_log2FC) > analysis_params$logFCfilter &         pbmc_markers$p_val_adj < analysis_params$adjPvalFilter),      ]
      if (nrow(sig_markers_group) > 0) {        sig_markers_group <- cbind(Gene = rownames(sig_markers_group), sig_markers_group)
        # Clean special characters in filename        safe_cell_name <- gsub("[^A-Za-z0-9_]", "_", cellName)
        write.table(          sig_markers_group,          file = file.path(output_dirs$differential_analysis, paste0(safe_cell_name, "_diffGenes.txt")),          sep = "\t",          row.names = FALSE,          quote = FALSE        )
        differential_results[[cellName]] <- sig_markers_group        message(sprintf("Saved %d differential genes for %s", nrow(sig_markers_group), cellName))        message(sprintf("保存 %s 的 %d 个差异基因", cellName, nrow(sig_markers_group)))      } else {        message(sprintf("No significant differential genes found for %s", cellName))        message(sprintf("未找到 %s 的显著差异基因", cellName))      }    }, error = function(e) {      message(sprintf("Error analyzing %s: %s", cellName, e$message))      message(sprintf("分析 %s 时出错: %s", cellName, e$message))    })  } else {    message(sprintf("Skipping %s - insufficient cells", cellName))    message(sprintf("跳过 %s - 细胞数量不足", cellName))  }}
# ==============================================================================# 12. Cell Proportion Analysis# ==============================================================================
