p <- ggplot(proportion_summary, aes(x = Group, y = Proportion, fill = CellType)) +  geom_bar(stat = "identity", width = 0.6, color = "black", size = 0.3) +  scale_fill_manual(values = celltype_colors, name = "Cell Type") +  scale_y_continuous(limits = c(0, 1), labels = scales::percent) +  theme_classic() +  theme(    axis.title.x = element_blank(),    axis.title.y = element_text(size = 14, face = "bold"),    axis.text.x = element_text(size = 12, face = "bold"),    axis.text.y = element_text(size = 10),    legend.position = "right",    legend.title = element_text(size = 12, face = "bold"),    legend.text = element_text(size = 10),    plot.title = element_text(hjust = 0.5, size = 16, face = "bold")  ) +  labs(title = "Cell Type Proportions: control vs Disease", y = "Proportion")
print(p)dev.off()
# ==============================================================================# 13. Individual Gene UMAP Distribution Analysis# ==============================================================================
message("Performing individual gene UMAP distribution analysis...")message("进行单基因UMAP分布分析...")
# Create output directory for individual gene analysisindividual_gene_dir <- "14.Individual_Gene_UMAP"output_dirs$individual_gene_umap <- individual_gene_dir
# Create main directory and subdirectoriesfull_path <- file.path(workDir, individual_gene_dir)if (!dir.exists(full_path)) {  dir.create(full_path, recursive = TRUE)  message(sprintf("Created directory: %s", individual_gene_dir))}
# Create subdirectories for each genegene_subdirs <- c("Individual_FeaturePlots", "Combined_Analysis", "Gene_Statistics")for (subdir in gene_subdirs) {  subdir_path <- file.path(full_path, subdir)  if (!dir.exists(subdir_path)) {    dir.create(subdir_path, recursive = TRUE)  }}
# Check if genes existavailable_genes <- showGenes[showGenes %in% rownames(GetAssayData(Peripheral_Blood_Mononuclear_Cells, assay = "RNA", layer = "data"))]missing_genes <- setdiff(showGenes, available_genes)
if (length(missing_genes) > 0) {  message(paste("The following genes were not found in the dataset:", paste(missing_genes, collapse = ", ")))  message(paste("以下基因未在数据集中找到:", paste(missing_genes, collapse = ", ")))}
if (length(available_genes) > 0) {  message(sprintf("Starting individual gene UMAP analysis for %d available genes", length(available_genes)))  message(sprintf("开始为 %d 个可用基因进行单基因UMAP分析", length(available_genes)))
  # Function to create individual gene UMAP plots  create_individual_gene_plots <- function(seurat_obj, gene, output_dir) {
    # Check if gene exists in the Seurat object first    if (!gene %in% rownames(seurat_obj)) {      message(sprintf("ERROR: Gene %s not found in Seurat object, skipping...", gene))      message(sprintf("错误：基因 %s 未在Seurat对象中找到，跳过...", gene))      return(NULL)    }
    # 1. Basic FeaturePlot    message(sprintf("Creating basic FeaturePlot for gene: %s", gene))
    pdf(file.path(output_dir, "Individual_FeaturePlots", paste0(gene, "_UMAP_FeaturePlot.pdf")),        width = 8, height = 6)    print(      FeaturePlot(        seurat_obj,        features = gene,        reduction = "umap",        cols = c("lightgrey", "#FF0000"),        pt.size = 1.2,        label = TRUE,        label.size = 3      ) +      ggtitle(paste(gene, "Expression (UMAP)")) +      theme_minimal() +      theme(        panel.grid.major = element_blank(),        panel.grid.minor = element_blank(),        axis.line = element_line(color = "black"),        axis.text = element_text(color = "black"),        axis.title = element_text(color = "black", face = "bold"),        plot.title = element_text(size = 16, face = "bold", hjust = 0.5)      )    )    dev.off()
    # 2. Combined analysis with cell type annotation (UMAP + Legend style)    message(sprintf("Creating combined analysis plot for gene: %s", gene))
    # Get UMAP embeddings    umap_df <- as.data.frame(Embeddings(seurat_obj, "umap"))    colnames(umap_df) <- c("UMAP_1", "UMAP_2")
    # Add metadata    umap_df$Cluster <- as.character(seurat_obj$seurat_clusters)    umap_df$CellType <- as.character(Idents(seurat_obj))    umap_df$Group <- seurat_obj$Type
    # Check if gene exists before fetching    if (!gene %in% rownames(seurat_obj)) {      message(sprintf("Warning: Gene %s not found in Seurat object", gene))      return(NULL)    }
    umap_df$Expression <- FetchData(seurat_obj, vars = gene)[,1]
    # Calculate cluster centers for labeling    label_df <- umap_df %>%      group_by(Cluster, CellType) %>%      summarise(        UMAP_1 = mean(UMAP_1),        UMAP_2 = mean(UMAP_2),        .groups = "drop"      )
    # Calculate cluster statistics for bar plot    cluster_stats <- umap_df %>%      group_by(Cluster, CellType) %>%      summarise(        AvgExpr = mean(Expression),        .groups = "drop"      ) %>%      arrange(as.numeric(Cluster))
    # Create color scheme for clusters    cluster_levels <- sort(unique(umap_df$Cluster))    cluster_colors <- setNames(colorRampPalette(brewer.pal(min(12, length(cluster_levels)), "Set3"))(length(cluster_levels)), cluster_levels)
    # UMAP main plot (similar to reference style)    p_umap <- ggplot(umap_df, aes(x = UMAP_1, y = UMAP_2)) +      geom_point(aes(color = factor(Cluster)), size = 1.2, alpha = 0.7) +      scale_color_manual(values = cluster_colors, name = "Cluster") +      geom_text(        data = label_df,        aes(label = paste0("C", Cluster, "\\n", CellType)),        color = "black",        size = 3.5,        fontface = "bold"      ) +      theme_classic(base_size = 14) +      ggtitle(gene) +      theme(        plot.title = element_text(size = 18, face = "bold", hjust = 0.5),        legend.position = "none",        axis.line = element_line(color = "black"),        axis.text = element_text(color = "black"),        axis.title = element_text(color = "black", face = "bold")      )
    # Bar plot (legend) showing average expression    cluster_stats$ClusterLabel <- paste0("C", cluster_stats$Cluster)    cluster_stats$ClusterLabel <- factor(cluster_stats$ClusterLabel, levels = paste0("C", cluster_levels))    max_expr <- max(cluster_stats$AvgExpr)    offset <- max_expr * 0.05
    p_legend <- ggplot(cluster_stats, aes(x = ClusterLabel, y = AvgExpr, fill = Cluster)) +      geom_bar(stat = "identity", width = 0.7) +      scale_fill_manual(values = cluster_colors, guide = "none") +      geom_text(        aes(x = ClusterLabel, y = AvgExpr + offset, label = CellType),        hjust = 0, vjust = 0.5, size = 4, fontface = "plain", color = "black"      ) +      coord_flip(clip = "off") +      labs(x = NULL, y = "Average Expression", title = "") +      theme_minimal(base_size = 12) +      theme(        axis.text.y = element_text(size = 11, face = "bold"),        axis.text.x = element_text(size = 10),        axis.title.x = element_text(size = 12, face = "bold"),        plot.margin = ggplot2::margin(5, 80, 5, 5),        panel.grid.major = element_blank(),        panel.grid.minor = element_blank(),        axis.line = element_line(color = "black")      )
    # Combined plot using patchwork (like reference style)    combined_plot <- p_umap + p_legend + plot_layout(widths = c(2.5, 1.2))
    pdf(file.path(output_dir, "Combined_Analysis", paste0(gene, "_UMAP_Combined_Analysis.pdf")),        width = 12, height = 6)    print(combined_plot)    dev.off()
    # Also create individual group comparison plots    message(sprintf("Creating group comparison plots for gene: %s", gene))
    for (group_name in unique(umap_df$Group)) {      group_data <- umap_df[umap_df$Group == group_name, ]
      # Calculate group-specific cluster centers      group_label_df <- group_data %>%        group_by(Cluster, CellType) %>%        summarise(          UMAP_1 = mean(UMAP_1),          UMAP_2 = mean(UMAP_2),          .groups = "drop"        )
      # Group-specific cluster statistics      group_cluster_stats <- group_data %>%        group_by(Cluster, CellType) %>%        summarise(          AvgExpr = mean(Expression),          .groups = "drop"        ) %>%        arrange(as.numeric(Cluster))
      # UMAP plot for this group      p_group_umap <- ggplot(group_data, aes(x = UMAP_1, y = UMAP_2)) +        geom_point(aes(color = factor(Cluster)), size = 1.2, alpha = 0.7) +        scale_color_manual(values = cluster_colors, name = "Cluster") +        geom_text(          data = group_label_df,          aes(label = paste0("C", Cluster)),          color = "black",          size = 3.5,          fontface = "bold"        ) +        theme_classic(base_size = 14) +        ggtitle(paste(gene, "-", group_name)) +        theme(          plot.title = element_text(size = 16, face = "bold", hjust = 0.5),          legend.position = "none",          axis.line = element_line(color = "black"),          axis.text = element_text(color = "black"),          axis.title = element_text(color = "black", face = "bold")        )
      # Bar plot for this group      if (nrow(group_cluster_stats) > 0) {        group_cluster_stats$ClusterLabel <- paste0("C", group_cluster_stats$Cluster)        group_cluster_stats$ClusterLabel <- factor(group_cluster_stats$ClusterLabel,                                                   levels = paste0("C", cluster_levels))        group_max_expr <- max(group_cluster_stats$AvgExpr)        group_offset <- group_max_expr * 0.05
        p_group_legend <- ggplot(group_cluster_stats, aes(x = ClusterLabel, y = AvgExpr, fill = Cluster)) +          geom_bar(stat = "identity", width = 0.7) +          scale_fill_manual(values = cluster_colors, guide = "none") +          geom_text(            aes(x = ClusterLabel, y = AvgExpr + group_offset, label = CellType),            hjust = 0, vjust = 0.5, size = 4, fontface = "plain", color = "black"          ) +          coord_flip(clip = "off") +          labs(x = NULL, y = "Average Expression", title = "") +          theme_minimal(base_size = 12) +          theme(            axis.text.y = element_text(size = 11, face = "bold"),            axis.text.x = element_text(size = 10),            axis.title.x = element_text(size = 12, face = "bold"),            plot.margin = ggplot2::margin(5, 80, 5, 5),            panel.grid.major = element_blank(),            panel.grid.minor = element_blank(),            axis.line = element_line(color = "black")          )
        # Combined group plot        group_combined_plot <- p_group_umap + p_group_legend + plot_layout(widths = c(2.5, 1.2))
        pdf(file.path(output_dir, "Combined_Analysis", paste0(gene, "_UMAP_", group_name, "_Analysis.pdf")),            width = 12, height = 6)        print(group_combined_plot)        dev.off()      }    }
    # 4. Export expression statistics    message(sprintf("Exporting statistics for gene: %s", gene))
    # Average expression by cell type and group    avg_by_celltype_group <- umap_df %>%      group_by(CellType, Group) %>%      summarise(        Cell_Count = n(),        Mean_Expression = mean(Expression),        Median_Expression = median(Expression),        SD_Expression = sd(Expression),        .groups = "drop"      ) %>%      arrange(CellType, Group)
    # Average expression by cluster and group    avg_by_cluster_group <- umap_df %>%      group_by(Cluster, Group) %>%      summarise(        Cell_Count = n(),        Mean_Expression = mean(Expression),        Median_Expression = median(Expression),        SD_Expression = sd(Expression),        .groups = "drop"      ) %>%      arrange(Cluster, Group)
    # Save statistics    write.csv(avg_by_celltype_group,              file.path(output_dir, "Gene_Statistics", paste0(gene, "_Expression_by_CellType_Group.csv")),              row.names = FALSE)    write.csv(avg_by_cluster_group,              file.path(output_dir, "Gene_Statistics", paste0(gene, "_Expression_by_Cluster_Group.csv")),              row.names = FALSE)
    # Save individual cell expression data    cell_expr_data <- data.frame(      Cell_ID = rownames(umap_df),      Cluster = umap_df$Cluster,      CellType = umap_df$CellType,      Group = umap_df$Group,      UMAP_1 = umap_df$UMAP_1,      UMAP_2 = umap_df$UMAP_2,      Expression = umap_df$Expression    )
    write.csv(cell_expr_data,              file.path(output_dir, "Gene_Statistics", paste0(gene, "_Individual_Cell_Expression.csv")),              row.names = FALSE)
    message(sprintf("Completed analysis for gene: %s", gene))    message(sprintf("基因 %s 分析完成", gene))
    return(list(      expression_data = umap_df,      celltype_stats = avg_by_celltype_group,      cluster_stats = avg_by_cluster_group    ))  }
  # Process each gene  gene_results <- list()  for (gene in available_genes) {    tryCatch({      gene_results[[gene]] <- create_individual_gene_plots(        Peripheral_Blood_Mononuclear_Cells,        gene,        full_path      )    }, error = function(e) {      message(sprintf("Error processing gene %s: %s", gene, e$message))      message(sprintf("处理基因 %s 时出错: %s", gene, e$message))    })  }
  # Create comprehensive summary report  message("Creating comprehensive gene expression summary...")  message("创建综合基因表达汇总...")
  if (length(gene_results) > 0) {    # Combine all cell type statistics    all_celltype_stats <- data.frame()    all_cluster_stats <- data.frame()
    for (gene in names(gene_results)) {      if (!is.null(gene_results[[gene]]$celltype_stats)) {        celltype_stats <- gene_results[[gene]]$celltype_stats        celltype_stats$Gene <- gene        all_celltype_stats <- rbind(all_celltype_stats, celltype_stats)      }
      if (!is.null(gene_results[[gene]]$cluster_stats)) {        cluster_stats <- gene_results[[gene]]$cluster_stats        cluster_stats$Gene <- gene        all_cluster_stats <- rbind(all_cluster_stats, cluster_stats)      }    }
    # Save comprehensive summaries    write.csv(all_celltype_stats,              file.path(full_path, "Gene_Statistics", "All_Genes_CellType_Expression_Summary.csv"),              row.names = FALSE)    write.csv(all_cluster_stats,              file.path(full_path, "Gene_Statistics", "All_Genes_Cluster_Expression_Summary.csv"),              row.names = FALSE)
    # Create summary statistics    gene_summary <- all_celltype_stats %>%      group_by(Gene, Group) %>%      summarise(        Total_CellTypes = n(),        Avg_Expression_Across_CellTypes = mean(Mean_Expression, na.rm = TRUE),        Max_Expression = max(Mean_Expression, na.rm = TRUE),        Min_Expression = min(Mean_Expression, na.rm = TRUE),        .groups = "drop"      ) %>%      pivot_wider(        names_from = Group,        values_from = c(Avg_Expression_Across_CellTypes, Max_Expression, Min_Expression),        names_sep = "_"      )
    write.csv(gene_summary,              file.path(full_path, "Gene_Statistics", "Gene_Expression_Summary_by_Group.csv"),              row.names = FALSE)
    message("Individual gene UMAP distribution analysis completed successfully!")    message("单基因UMAP分布分析成功完成！")    message(sprintf("Analyzed %d genes with complete statistics and visualizations", length(available_genes)))    message(sprintf("分析了 %d 个基因，包含完整的统计和可视化结果", length(available_genes)))  }
} else {  message("No genes available for individual UMAP analysis")  message("没有可用于单基因UMAP分析的基因")}
