# Define galaxy theme function# Note: Use ggplot2::margin() explicitly to avoid namespace conflictsgalaxyTheme_black = function(base_size = 12, base_family = "") {  ggplot2::theme_grey(base_size = base_size, base_family = base_family) %+replace%    ggplot2::theme(      # Specify axis options      axis.line = ggplot2::element_blank(),      axis.text.x = ggplot2::element_text(size = base_size*0.8, color = "white", lineheight = 0.9),      axis.text.y = ggplot2::element_text(size = base_size*0.8, color = "white", lineheight = 0.9),      axis.ticks = ggplot2::element_line(color = "white", linewidth = 0.2),      axis.title.x = ggplot2::element_text(size = base_size, color = "white", margin = ggplot2::margin(t = 10, unit = "pt")),      axis.title.y = ggplot2::element_text(size = base_size, color = "white", angle = 90, margin = ggplot2::margin(r = 10, unit = "pt")),      axis.ticks.length = grid::unit(0.3, "lines"),      # Specify legend options      legend.background = ggplot2::element_rect(color = NA, fill = "black"),      legend.key = ggplot2::element_rect(color = "white", fill = "black"),      legend.key.size = grid::unit(1.2, "lines"),      legend.key.height = NULL,      legend.key.width = NULL,      legend.text = ggplot2::element_text(size = base_size*0.8, color = "white"),      legend.title = ggplot2::element_text(size = base_size*0.8, face = "bold", hjust = 0, color = "white"),      legend.position = "none",      legend.text.align = NULL,      legend.title.align = NULL,      legend.direction = "vertical",      legend.box = NULL,      # Specify panel options      panel.background = ggplot2::element_rect(fill = "black", color = NA),      panel.border = ggplot2::element_rect(fill = NA, color = "white"),      panel.grid.major = ggplot2::element_blank(),      panel.grid.minor = ggplot2::element_blank(),      panel.spacing = grid::unit(0.5, "lines"),      # Specify facetting options      strip.background = ggplot2::element_rect(fill = "grey30", color = "grey10"),      strip.text.x = ggplot2::element_text(size = base_size*0.8, color = "white"),      strip.text.y = ggplot2::element_text(size = base_size*0.8, color = "white", angle = -90),      # Specify plot options      plot.background = ggplot2::element_rect(color = "black", fill = "black"),      plot.title = ggplot2::element_text(size = base_size*1.2, color = "white"),      plot.margin = grid::unit(rep(1, 4), "lines")    )}
# Prepare nebula plot dataumap_coords <- Embeddings(Peripheral_Blood_Mononuclear_Cells, "umap")nebula_plot_data <- data.frame(  UMAP_1 = umap_coords[, 1],  UMAP_2 = umap_coords[, 2],  cell_type = as.character(Idents(Peripheral_Blood_Mononuclear_Cells)),  group = Peripheral_Blood_Mononuclear_Cells$Type)
# Add sample count labels to groupsgroup_counts <- table(nebula_plot_data$group)nebula_plot_data$group_label <- factor(nebula_plot_data$group,                                       levels = names(group_counts),                                       labels = paste0(names(group_counts), "\n(n = ", group_counts, ")"))
message(sprintf("Nebula plot data prepared with %d cells", nrow(nebula_plot_data)))message(sprintf("星云图数据准备完成，共 %d 个细胞", nrow(nebula_plot_data)))
# Define outlier removal function for better convex hullsremove_outlier <- function(x, y, proportion = 0.9) {  stopifnot(length(x) == length(y))  distance_to_centroid <- (x - mean(x))^2 + (y - mean(y))^2  kept_site <- order(distance_to_centroid)[1:ceiling(length(x) * proportion)]  return(kept_site)}
# Calculate all cell typesall_celltypes <- unique(nebula_plot_data$cell_type)all_celltypes <- all_celltypes[all_celltypes != "boundary"]message(sprintf("Found %d cell types for nebula plot", length(all_celltypes)))message(sprintf("星云图包含 %d 种细胞类型", length(all_celltypes)))
# Create improved hull data for all cell typeshull_data_improved <- lapply(all_celltypes, function(ct) {  ct_data <- nebula_plot_data[nebula_plot_data$cell_type == ct, ]  if (nrow(ct_data) >= analysis_params$hull_min_points) {    kept_indices <- remove_outlier(ct_data$UMAP_1, ct_data$UMAP_2,                                   proportion = analysis_params$hull_outlier_proportion)    return(ct_data[kept_indices, ])  } else {    return(ct_data)  }})names(hull_data_improved) <- all_celltypes
# Combine improved hull datahull_data_clean <- do.call(rbind, hull_data_improved[lengths(hull_data_improved) > 0])
# =============================================# Generate grouped nebula plot (by group)# =============================================message("Generating grouped nebula plot...")message("生成分组星云图...")
# Create boundary points for grouped plotgroup_range_x <- c(min(nebula_plot_data$UMAP_1) - analysis_params$nebula_coord_extend_group,                   max(nebula_plot_data$UMAP_1) + analysis_params$nebula_coord_extend_group)group_range_y <- c(min(nebula_plot_data$UMAP_2) - analysis_params$nebula_coord_extend_group,                   max(nebula_plot_data$UMAP_2) + analysis_params$nebula_coord_extend_group)
# Create boundary points for each groupboundary_points_group <- do.call(rbind, lapply(unique(nebula_plot_data$group), function(grp) {  grp_label <- paste0(grp, "\n(n = ", table(nebula_plot_data$group)[grp], ")")  data.frame(    UMAP_1 = c(      rep(group_range_x, each = 15),      rep(seq(group_range_x[1], group_range_x[2], length.out = 15), 2)    ),    UMAP_2 = c(      rep(c(group_range_y[1], group_range_y[2]), each = 15),      rep(group_range_y, each = 15)    ),    cell_type = "boundary",    group = grp,    group_label = grp_label  )}))
# Merge original data and boundary pointsextended_data_group <- rbind(nebula_plot_data, boundary_points_group)
# Create galaxy plot with densitygalaxy_plot <- ggplot() +  stat_density_2d(    data = extended_data_group,    aes(x = UMAP_1, y = UMAP_2, fill = after_stat(density)),    geom = "raster",    contour = FALSE,    n = analysis_params$nebula_density_n_group,    adjust = analysis_params$nebula_density_adjust_group  ) +  geom_point(    data = nebula_plot_data,    aes(x = UMAP_1, y = UMAP_2),    color = analysis_params$nebula_point_color,    size = analysis_params$nebula_point_size,    alpha = analysis_params$nebula_point_alpha  ) +  viridis::scale_fill_viridis(option = "magma", direction = 1) +  coord_cartesian(    xlim = group_range_x,    ylim = group_range_y,    expand = FALSE  ) +  facet_wrap(~group_label, ncol = 2) +  galaxyTheme_black(base_size = 16) +  labs(x = "UMAP_1", y = "UMAP_2", title = "Cell Type Distribution - Nebula View") +  theme(    legend.position = "none",    plot.margin = ggplot2::margin(25, 25, 25, 25, "pt"),    axis.title.x = element_text(margin = ggplot2::margin(12, 0, 0, 0, "pt")),    axis.title.y = element_text(margin = ggplot2::margin(0, 12, 0, 0, "pt")),    panel.border = element_rect(fill = NA, color = "white", size = 0.3),    panel.spacing = unit(1, "lines")  )
# Add improved convex hulls and labelsif (nrow(hull_data_clean) > 0) {  hull_celltype_counts <- table(hull_data_clean$cell_type)  valid_celltypes <- names(hull_celltype_counts[hull_celltype_counts >= 5])  hull_data_for_plot <- hull_data_clean[hull_data_clean$cell_type %in% valid_celltypes, ]
  if (nrow(hull_data_for_plot) > 0) {    tryCatch({      # Add convex hulls      galaxy_plot <- galaxy_plot +        ggforce::geom_mark_hull(          data = hull_data_for_plot,          aes(x = UMAP_1, y = UMAP_2, group = cell_type),          linewidth = analysis_params$hull_linewidth_group,          concavity = analysis_params$hull_concavity_group,          color = 'white',          expand = unit(analysis_params$hull_expand_group, "mm"),          linetype = 'dashed',          fill = NA,          alpha = 0.8        )
      # Add cell type labels      celltype_centers <- hull_data_for_plot %>%        group_by(cell_type) %>%        summarise(          center_x = mean(UMAP_1),          center_y = mean(UMAP_2),          .groups = 'drop'        )
      galaxy_plot <- galaxy_plot +        geom_text(          data = celltype_centers,          aes(x = center_x, y = center_y, label = cell_type),          color = 'white',          size = analysis_params$hull_label_fontsize_group / 3,          fontface = 'bold'        )    }, error = function(e) {      message(sprintf("Warning: Convex hull plotting failed - %s", e$message))      message(sprintf("警告：凸包绘制失败 - %s", e$message))    })  }}
# Save grouped nebula plotpdf(file.path(output_dirs$nebula_plots, "01_Nebula_Plot_by_Group.pdf"), width = 12, height = 8)print(galaxy_plot)dev.off()
message("Grouped nebula plot saved")message("分组星云图已保存")
# =============================================# Generate single nebula plot (all cells)# =============================================message("Generating single nebula plot...")message("生成单一星云图...")
# Create extended data rangeextended_range_x <- c(min(nebula_plot_data$UMAP_1) - analysis_params$nebula_coord_extend_single,                      max(nebula_plot_data$UMAP_1) + analysis_params$nebula_coord_extend_single)extended_range_y <- c(min(nebula_plot_data$UMAP_2) - analysis_params$nebula_coord_extend_single,                      max(nebula_plot_data$UMAP_2) + analysis_params$nebula_coord_extend_single)
# Create boundary pointsboundary_points <- data.frame(  UMAP_1 = c(    rep(extended_range_x, each = 20),    rep(seq(extended_range_x[1], extended_range_x[2], length.out = 20), 2)  ),  UMAP_2 = c(    rep(c(extended_range_y[1], extended_range_y[2]), each = 20),    rep(extended_range_y, each = 20)  ),  cell_type = "boundary",  group = "boundary",  group_label = "boundary")
# Merge dataextended_data <- rbind(nebula_plot_data, boundary_points)
# Create single galaxy plotgalaxy_plot_single <- ggplot() +  stat_density_2d(    data = extended_data,    aes(x = UMAP_1, y = UMAP_2, fill = after_stat(density)),    geom = "raster",    contour = FALSE,    n = analysis_params$nebula_density_n_single,    adjust = analysis_params$nebula_density_adjust_single  ) +  geom_point(    data = nebula_plot_data,    aes(x = UMAP_1, y = UMAP_2),    color = analysis_params$nebula_point_color,    size = analysis_params$nebula_point_size,    alpha = analysis_params$nebula_point_alpha  ) +  viridis::scale_fill_viridis(option = "magma", direction = 1) +  coord_cartesian(    xlim = extended_range_x,    ylim = extended_range_y,    expand = FALSE  ) +  galaxyTheme_black(base_size = 18) +  labs(x = "UMAP_1", y = "UMAP_2", title = "Cell Distribution - Nebula View") +  theme(    legend.position = "none",    plot.margin = ggplot2::margin(30, 30, 30, 30, "pt"),    axis.title.x = element_text(margin = ggplot2::margin(15, 0, 0, 0, "pt")),    axis.title.y = element_text(margin = ggplot2::margin(0, 15, 0, 0, "pt")),    panel.border = element_rect(fill = NA, color = "white", size = 0.3)  )
# Add convex hulls for single plotif (nrow(hull_data_clean) > 0) {  hull_celltype_counts <- table(hull_data_clean$cell_type)  valid_celltypes <- names(hull_celltype_counts[hull_celltype_counts >= 5])  hull_data_for_plot_single <- hull_data_clean[hull_data_clean$cell_type %in% valid_celltypes, ]
  if (nrow(hull_data_for_plot_single) > 0) {    tryCatch({      galaxy_plot_single <- galaxy_plot_single +        ggforce::geom_mark_hull(          data = hull_data_for_plot_single,          aes(x = UMAP_1, y = UMAP_2, group = cell_type),          linewidth = analysis_params$hull_linewidth_single,          concavity = analysis_params$hull_concavity_single,          color = 'white',          expand = unit(analysis_params$hull_expand_single, "mm"),          linetype = 'dashed',          fill = NA,          alpha = 0.9        )
      celltype_centers_single <- hull_data_for_plot_single %>%        group_by(cell_type) %>%        summarise(          center_x = mean(UMAP_1),          center_y = mean(UMAP_2),          .groups = 'drop'        )
      galaxy_plot_single <- galaxy_plot_single +        geom_text(          data = celltype_centers_single,          aes(x = center_x, y = center_y, label = cell_type),          color = 'white',          size = analysis_params$hull_label_fontsize_single / 3,          fontface = 'bold'        )    }, error = function(e) {      message(sprintf("Warning: Single plot convex hull failed - %s", e$message))      message(sprintf("警告：单一图凸包绘制失败 - %s", e$message))    })  }}
# Save single nebula plotpdf(file.path(output_dirs$nebula_plots, "02_Nebula_Plot_Single.pdf"), width = 10, height = 8)print(galaxy_plot_single)dev.off()
