get_count_matrix <- function(seurat_obj, assay_name) {  tryCatch(    GetAssayData(seurat_obj, assay = assay_name, layer = "counts"),    error = function(e) GetAssayData(seurat_obj, assay = assay_name, slot = "counts")  )}
prepare_knockout_input <- function(count_mat,                                   selected_genes,                                   target_gene,                                   gene_min_cells,                                   min_cells_after_filter,                                   min_genes_after_filter) {  data_mat <- as.matrix(count_mat[selected_genes, , drop = FALSE])  if (!is.matrix(data_mat) || length(dim(data_mat)) != 2) {    stop("敲除输入矩阵构建失败，未得到二维表达矩阵。")  }  if (anyDuplicated(rownames(data_mat)) > 0) {    data_mat <- data_mat[!duplicated(rownames(data_mat)), , drop = FALSE]  }
  detected_cells <- rowSums(data_mat != 0)  keep_genes <- detected_cells >= gene_min_cells | rownames(data_mat) == target_gene  data_mat <- data_mat[keep_genes, , drop = FALSE]
  keep_cells <- colSums(data_mat) > 0  data_mat <- data_mat[, keep_cells, drop = FALSE]
  if (ncol(data_mat) < min_cells_after_filter) {    stop(sprintf("过滤后仅剩 %d 个细胞，低于最小要求 %d。", ncol(data_mat), min_cells_after_filter))  }  if (nrow(data_mat) < min_genes_after_filter) {    stop(sprintf("过滤后仅剩 %d 个基因，低于最小要求 %d。", nrow(data_mat), min_genes_after_filter))  }  if (!target_gene %in% rownames(data_mat)) {    stop(sprintf("过滤后敲除基因 %s 不在输入矩阵中。", target_gene))  }
  storage.mode(data_mat) <- "double"
  list(    matrix = data_mat,    cells_used = ncol(data_mat),    genes_used = nrow(data_mat)  )}
strict_direction_fn <- getFromNamespace("strictDirection", "scTenifoldKnk")dregulation_fn <- getFromNamespace("dRegulation", "scTenifoldKnk")
safe_manifold_alignment <- function(X, Y, d = 2L, nCores = 1L) {  shared_genes <- Reduce(intersect, list(    rownames(X), colnames(X),    rownames(Y), colnames(Y)  ))  if (length(shared_genes) < 2L) {    stop("共享基因数量过少，无法进行 manifold alignment。")  }
  X <- X[shared_genes, shared_genes, drop = FALSE]  Y <- Y[shared_genes, shared_genes, drop = FALSE]
  L <- diag(length(shared_genes))  wX <- X + 1  wY <- Y + 1  wXY <- 0.9 * (sum(wX) + sum(wY)) / (2 * sum(L)) * L  W <- rbind(cbind(wX, wXY), cbind(t(wXY), wY))  W <- -W  diag(W) <- 0  diag(W) <- -apply(W, 2, sum)
  nCores <- suppressWarnings(as.integer(nCores[1]))  if (!is.finite(nCores) || is.na(nCores) || nCores < 1L) {    nCores <- 1L  }  if (requireNamespace("RhpcBLASctl", quietly = TRUE)) {    RhpcBLASctl::omp_set_num_threads(nCores)    RhpcBLASctl::blas_set_num_threads(nCores)  }
  requested_d <- as.integer(d)  eig_k <- min(max(requested_d * 2L, 4L), nrow(W) - 1L)  eig_k_max <- min(max(requested_d * 32L, eig_k), nrow(W) - 1L)  if (!is.finite(eig_k) || is.na(eig_k) || eig_k < 1L) {    stop("网络矩阵维度过小，无法进行特征分解。")  }
  eigen_values <- NULL  eigen_vectors <- NULL  keep_dims <- integer(0)  threshold_used <- 1e-08  current_k <- eig_k
  repeat {    E <- suppressWarnings(RSpectra::eigs(W, current_k, "SR"))    eigen_values <- suppressWarnings(as.numeric(E$values))    eigen_vectors <- E$vectors    if (is.null(dim(eigen_vectors))) {      eigen_vectors <- matrix(as.numeric(eigen_vectors), ncol = 1L)    } else {      storage.mode(eigen_vectors) <- "double"    }
    new_order <- order(eigen_values)    eigen_values <- eigen_values[new_order]    eigen_vectors <- eigen_vectors[, new_order, drop = FALSE]
    keep_dims <- which(is.finite(eigen_values) & eigen_values > 1e-08)    threshold_used <- 1e-08    if (length(keep_dims) == 0L) {      keep_dims <- which(is.finite(eigen_values) & eigen_values > 0)      threshold_used <- 0    }    if (length(keep_dims) == 0L) {      keep_dims <- which(is.finite(eigen_values) & eigen_values > -1e-08)      threshold_used <- -1e-08    }
    if (length(keep_dims) >= requested_d || current_k >= eig_k_max) {      break    }
    next_k <- min(max(current_k * 2L, current_k + 2L), eig_k_max)    if (next_k <= current_k) {      break    }    message(sprintf("  Manifold alignment 正特征维度不足，特征分解 k 从 %d 扩展到 %d", current_k, next_k))    current_k <- next_k  }
  if (length(keep_dims) == 0L) {    stop("manifold alignment 未获得有效特征向量。")  }  if (threshold_used < 1e-08) {    message(sprintf("  Manifold alignment 使用放宽阈值 %.1e 选择有效特征向量", threshold_used))  }
  eigen_vectors <- eigen_vectors[, keep_dims, drop = FALSE]  aligned_d <- min(requested_d, ncol(eigen_vectors))  if (aligned_d < 1L) {    stop("manifold alignment 可用维度不足。")  }  if (aligned_d < requested_d) {    message(sprintf("  Manifold alignment 有效维度不足，自动将 d 从 %d 调整为 %d", requested_d, aligned_d))  }
  aligned_net <- eigen_vectors[, seq_len(aligned_d), drop = FALSE]  colnames(aligned_net) <- paste0("NLMA ", seq_len(aligned_d))  rownames(aligned_net) <- c(paste0("X_", shared_genes), paste0("Y_", shared_genes))  attr(aligned_net, "aligned_d") <- aligned_d  aligned_net}
run_scTenifoldKnk_safe <- function(countMatrix,                                   gKO,                                   nc_nNet,                                   nc_nCells,                                   ma_nDim,                                   nCores = 1L) {  if (!requireNamespace("scTenifoldNet", quietly = TRUE)) {    stop("缺少 scTenifoldNet 包，无法使用稳健敲除流程。")  }  if (!gKO %in% rownames(countMatrix)) {    stop(sprintf("%s 不在输入表达矩阵中。", gKO))  }
  WT <- scTenifoldNet::makeNetworks(    X = countMatrix,    q = 0.9,    nNet = as.integer(nc_nNet),    nCells = as.integer(nc_nCells),    scaleScores = TRUE,    symmetric = FALSE,    nComp = 3L,    nCores = as.integer(nCores)  )  message(sprintf("  Network construction complete (nNet = %d, nCells per net = %d)",                  as.integer(nc_nNet), as.integer(nc_nCells)))
  WT <- scTenifoldNet::tensorDecomposition(    xList = WT,    K = 3L,    maxError = 1e-05,    maxIter = 1000L,    nDecimal = 3L  )  message("  Tensor decomposition completed (K = 3)")
  WT <- WT$X  WT <- strict_direction_fn(WT, lambda = 0)  WT <- as.matrix(WT)  diag(WT) <- 0  WT <- t(WT)  message("  Prepared WT adjacency matrix for KO simulation")
  KO <- WT  KO[gKO, ] <- 0  message(sprintf("  Simulated knockout for %s", gKO))
  MA <- safe_manifold_alignment(    X = WT,    Y = KO,    d = as.integer(ma_nDim),    nCores = as.integer(nCores)  )  message(sprintf("  Manifold alignment completed (d = %d)", attr(MA, "aligned_d")))
  DR <- dregulation_fn(MA, gKO)  message(sprintf("  Differential regulation computed for %s", gKO))
  list(    tensorNetworks = list(      WT = Matrix::Matrix(WT),      KO = Matrix::Matrix(KO)    ),    manifoldAlignment = MA,    diffRegulation = DR  )}
run_scTenifoldKnk_robust <- function(countMatrix,                                     gKO,                                     nc_nNet,                                     nc_nCells,                                     ma_nDim,                                     nCores = 1L) {  native_result <- tryCatch(    scTenifoldKnk(      countMatrix = countMatrix,      gKO = gKO,      qc = FALSE,      nc_nNet = as.integer(nc_nNet),      nc_nCells = as.integer(nc_nCells)    ),    error = function(e) e  )
  if (!inherits(native_result, "error")) {    return(native_result)  }
  message(sprintf("  Native scTenifoldKnk failed for %s: %s", gKO, conditionMessage(native_result)))  message("  Falling back to stable KO workflow...")  message("  原生scTenifoldKnk失败，切换到稳健敲除流程...")
  safe_result <- run_scTenifoldKnk_safe(    countMatrix = countMatrix,    gKO = gKO,    nc_nNet = nc_nNet,    nc_nCells = nc_nCells,    ma_nDim = ma_nDim,    nCores = nCores  )  attr(safe_result, "native_error") <- conditionMessage(native_result)  safe_result}
get_knockout_output_files <- function(gene_output_dir, knockout_gene) {  list(    tables = list(      runtime_config = file.path(gene_output_dir, "00_Knockout_Runtime_Config.txt"),      summary = file.path(gene_output_dir, "01_Knockout_Summary.csv"),      all_results = file.path(gene_output_dir, "02_Knockout_All_Results.csv"),      significant_results = file.path(gene_output_dir, "03_Knockout_Significant_Results.csv"),      error_log = file.path(gene_output_dir, "06_Knockout_Error.txt")    ),    plots = list(      scatter = file.path(gene_output_dir, "04_Knockout_Scatter.pdf"),      barplot = file.path(gene_output_dir, "05_Knockout_Barplot.pdf")    ),    legacy = list(      significant = file.path(gene_output_dir, paste0(knockout_gene, "_sigDiff.csv")),      all = file.path(gene_output_dir, paste0(knockout_gene, "_KO_allResults.csv")),      summary = file.path(gene_output_dir, paste0(knockout_gene, "_KO_summary.csv")),      scatter = file.path(gene_output_dir, paste0(knockout_gene, "_KO_scatter.pdf")),      barplot = file.path(gene_output_dir, paste0(knockout_gene, "_KO_barplot.pdf"))    )  )}
