run_disease_knockout_analysis <- function(seurat_obj,                                          knockout_gene,                                          output_dir,                                          params,                                          n_cores = NULL) {
  message(sprintf("\n--- Analyzing %s knockout in all Disease cells ---", knockout_gene))  message(sprintf("--- 分析 %s 在所有疾病组细胞中的敲除效应 ---", knockout_gene))
  gene_output_dir <- file.path(output_dir, paste0("Gene_", knockout_gene))  if (!dir.exists(gene_output_dir)) {    dir.create(gene_output_dir, recursive = TRUE)  }  output_files <- get_knockout_output_files(gene_output_dir, knockout_gene)
  tryCatch({    n_cells <- ncol(seurat_obj)    disease_celltypes <- sort(unique(as.character(Idents(seurat_obj))))    message(sprintf("  Using %d Disease cells", n_cells))    message(sprintf("  使用 %d 个疾病组细胞", n_cells))
    assay_name <- tryCatch(      as.character(Seurat::DefaultAssay(seurat_obj)),      error = function(e) "RNA"    )    count_matrix_full <- get_count_matrix(seurat_obj, assay_name = assay_name)
    if (!(knockout_gene %in% rownames(count_matrix_full))) {      stop(sprintf("基因 %s 不在 counts 矩阵中。", knockout_gene))    }
    ko_gene_expr <- sum(count_matrix_full[knockout_gene, ])    ko_gene_cells <- sum(count_matrix_full[knockout_gene, ] > 0)    ko_gene_pct <- ko_gene_cells / ncol(count_matrix_full) * 100    message(sprintf("  Knockout gene %s: total counts=%.0f, expressed in %.0f cells (%.1f%%)",                    knockout_gene, ko_gene_expr, ko_gene_cells, ko_gene_pct))
    hvg_features <- VariableFeatures(seurat_obj)    if (length(hvg_features) == 0) {      detected_cells_per_gene <- Matrix::rowSums(count_matrix_full > 0)      hvg_features <- names(sort(detected_cells_per_gene, decreasing = TRUE))      message("  WARNING: Variable genes unavailable, fallback to genes ranked by detected cell count")    }
    selected_features <- unique(c(knockout_gene, hvg_features))    selected_features <- selected_features[selected_features %in% rownames(count_matrix_full)]
    prepared_input <- prepare_knockout_input(      count_mat = count_matrix_full,      selected_genes = selected_features,      target_gene = knockout_gene,      gene_min_cells = params$gene_min_cells,      min_cells_after_filter = params$min_cells_after_filter,      min_genes_after_filter = params$min_genes_after_filter    )    expr_df <- prepared_input$matrix
    message(sprintf("  Expression matrix: %d genes x %d cells", nrow(expr_df), ncol(expr_df)))    message(sprintf("  表达矩阵: %d 基因 x %d 细胞", nrow(expr_df), ncol(expr_df)))    message("  Running scTenifoldKnk analysis...")    message("  运行scTenifoldKnk分析...")
    n_cells_for_net <- min(as.integer(params$nc_nCells), ncol(expr_df))    n_cores_use <- suppressWarnings(as.integer(if (is.null(n_cores)) 1L else n_cores[1]))    if (!is.finite(n_cores_use) || is.na(n_cores_use) || n_cores_use < 1L) {      n_cores_use <- 1L    }    if (n_cells_for_net < 50) {      warning(sprintf("基因 %s 可用于网络构建的细胞数较少（%d），结果可能不稳定。", knockout_gene, n_cells_for_net))    }
    knk_result <- run_scTenifoldKnk_robust(      countMatrix = expr_df,      gKO = knockout_gene,      nc_nNet = as.integer(params$nc_nNet),      nc_nCells = n_cells_for_net,      ma_nDim = as.integer(params$ma_nDim),      nCores = n_cores_use    )
    if (is.null(knk_result$diffRegulation)) {      stop("scTenifoldKnk 未返回有效结果。")    }
    diff_reg_genes <- as.data.frame(knk_result$diffRegulation, stringsAsFactors = FALSE)    if (nrow(diff_reg_genes) == 0) {      stop("scTenifoldKnk 未返回有效结果。")    }    required_cols <- c("gene", "FC")    missing_cols <- setdiff(required_cols, colnames(diff_reg_genes))    if (length(missing_cols) > 0) {      stop(sprintf("敲除结果缺少必要列：%s", paste(missing_cols, collapse = ", ")))    }
    if (!"p.adj" %in% colnames(diff_reg_genes)) {      if ("p.value" %in% colnames(diff_reg_genes)) {        diff_reg_genes$p.adj <- diff_reg_genes$p.value      } else {        stop("敲除结果缺少 p.adj / p.value 列。")      }    }    if (!"p.value" %in% colnames(diff_reg_genes)) {      diff_reg_genes$p.value <- diff_reg_genes$p.adj    }    if (!"Z" %in% colnames(diff_reg_genes)) {      diff_reg_genes$Z <- NA_real_    }
    numeric_cols <- intersect(c("distance", "Z", "FC", "p.value", "p.adj"), colnames(diff_reg_genes))    for (col in numeric_cols) {      diff_reg_genes[[col]] <- as.numeric(diff_reg_genes[[col]])    }
    diff_reg_genes <- diff_reg_genes %>%      dplyr::filter(gene != knockout_gene) %>%      dplyr::mutate(        log_p.adj = -log10(pmax(p.adj, .Machine$double.xmin)),        significant = ifelse(p.adj < params$pval_threshold, "Significant", "Not significant")      ) %>%      dplyr::arrange(p.adj, dplyr::desc(abs(FC)))
    sig_diff_genes <- diff_reg_genes %>%      dplyr::filter(p.adj < params$pval_threshold)
    message(sprintf("  Found %d differentially regulated genes", nrow(diff_reg_genes)))    message(sprintf("  其中显著差异调控基因 %d 个 (p.adj < %.3f)",                    nrow(sig_diff_genes), params$pval_threshold))
    knk_summary <- data.frame(      Gene = knockout_gene,      Cells_Used = prepared_input$cells_used,      Genes_Used = prepared_input$genes_used,      Significant_Genes = nrow(sig_diff_genes),      Top_Hit_Gene = if (nrow(diff_reg_genes) > 0) diff_reg_genes$gene[1] else NA_character_,      Top_Hit_FDR = if (nrow(diff_reg_genes) > 0) diff_reg_genes$p.adj[1] else NA_real_,      stringsAsFactors = FALSE    )
    knk_metadata <- data.frame(      Gene = knockout_gene,      Group = "Disease",      Disease_Cells = n_cells,      Network_Cells_Used = n_cells_for_net,      Cell_Types = paste(disease_celltypes, collapse = "; "),      Knockout_Gene_Total_Counts = as.numeric(ko_gene_expr),      Knockout_Gene_Expressed_Cells = as.numeric(ko_gene_cells),      Knockout_Gene_Expression_Pct = round(ko_gene_pct, 3),      stringsAsFactors = FALSE    )
    runtime_lines <- c(      paste0("Knockout_Gene: ", knockout_gene),      "Group: Disease",      paste0("Disease_Cells: ", n_cells),      paste0("Disease_Cell_Types: ", paste(disease_celltypes, collapse = ", ")),      paste0("Knockout_Gene_Total_Counts: ", format(round(ko_gene_expr, 0), scientific = FALSE, trim = TRUE)),      paste0("Knockout_Gene_Expressed_Cells: ", format(round(ko_gene_cells, 0), scientific = FALSE, trim = TRUE)),      paste0("Knockout_Gene_Expression_Pct: ", round(ko_gene_pct, 3)),      paste0("Cells_Used: ", prepared_input$cells_used),      paste0("Genes_Used: ", prepared_input$genes_used),      paste0("Network_Cells_Used: ", n_cells_for_net),      paste0("ma_nDim: ", params$ma_nDim),      paste0("n_cores: ", n_cores_use),      paste0("pval_threshold: ", params$pval_threshold)    )
    write_utf8_text(runtime_lines, output_files$tables$runtime_config)    write_utf8_csv(knk_summary, output_files$tables$summary, row.names = FALSE)    write_utf8_csv(diff_reg_genes, output_files$tables$all_results, row.names = FALSE)    write_utf8_csv(sig_diff_genes, output_files$tables$significant_results, row.names = FALSE)
    if (isTRUE(params$write_legacy_outputs)) {      write_utf8_csv(sig_diff_genes, output_files$legacy$significant, row.names = FALSE)      write_utf8_csv(diff_reg_genes, output_files$legacy$all, row.names = FALSE)      write_utf8_csv(knk_summary, output_files$legacy$summary, row.names = FALSE)    }
    valid_log_padj <- diff_reg_genes$log_p.adj[is.finite(diff_reg_genes$log_p.adj)]    y_upper <- 1    if (length(valid_log_padj) > 0) {      y_upper <- as.numeric(stats::quantile(valid_log_padj, 0.999, na.rm = TRUE))      if (!is.finite(y_upper) || y_upper <= 0) {        y_upper <- max(valid_log_padj)      }    }    if (!is.finite(y_upper) || y_upper <= 0) {      y_upper <- 1    }
    label_genes <- head(sig_diff_genes, 30)    scatter_colors <- c("Significant" = brewer.pal(8, "Set2")[2], "Not significant" = "gray70")    p_scatter <- ggplot(diff_reg_genes, aes(x = Z, y = log_p.adj, color = significant)) +      geom_point(alpha = 0.7, size = 1.5) +      geom_hline(        yintercept = -log10(params$pval_threshold),        linetype = "dashed",        color = scatter_colors["Significant"]      ) +      scale_color_manual(values = scatter_colors) +      coord_cartesian(ylim = c(0, y_upper)) +      labs(        title = paste0(knockout_gene, " Knockout"),        x = "Z-score",        y = "-log10(p.adj)"      ) +      theme_classic(base_size = 14) +      theme(        plot.title = element_text(hjust = 0.5, face = "bold", size = 16),        axis.title = element_text(size = 14, face = "bold"),        axis.text = element_text(size = 12),        legend.position = "none"      )
    if (nrow(label_genes) > 0) {      p_scatter <- p_scatter +        ggrepel::geom_text_repel(          data = label_genes,          aes(label = gene),          size = 3,          max.overlaps = 50,          color = "black",          fontface = "italic"        )    }
    pdf(output_files$plots$scatter, width = 6, height = 5)    print(p_scatter)    dev.off()    if (isTRUE(params$write_legacy_outputs)) {      file.copy(output_files$plots$scatter, output_files$legacy$scatter, overwrite = TRUE)    }
    top_genes <- head(diff_reg_genes[order(-abs(diff_reg_genes$FC), diff_reg_genes$p.adj), , drop = FALSE], 20)    if (nrow(top_genes) > 0) {      bar_colors <- colorRampPalette(brewer.pal(12, "Set3"))(nrow(top_genes))      p_bar <- ggplot(top_genes, aes(x = reorder(gene, FC), y = FC, fill = reorder(gene, FC))) +        geom_col(alpha = 0.9) +        coord_flip() +        scale_fill_manual(values = bar_colors) +        labs(          title = paste0("Top 20 Differentially Regulated Genes\n(", knockout_gene, " Knockout)"),          x = "Gene",          y = "FC"        ) +        theme_classic(base_size = 14) +        theme(          plot.title = element_text(hjust = 0.5, face = "bold", size = 14),          axis.title = element_text(size = 13, face = "bold"),          axis.text.y = element_text(size = 11, face = "italic"),          axis.text.x = element_text(size = 11),          legend.position = "none"        )
      pdf(output_files$plots$barplot, width = 6, height = 5)      print(p_bar)      dev.off()      if (isTRUE(params$write_legacy_outputs)) {        file.copy(output_files$plots$barplot, output_files$legacy$barplot, overwrite = TRUE)      }    }
    message(sprintf("  Results saved for %s", knockout_gene))
    return(list(      summary = knk_summary,      metadata = knk_metadata,      diff_genes = diff_reg_genes,      group = "Disease",      gene = knockout_gene    ))
  }, error = function(e) {    if (dev.cur() > 1) {      dev.off()    }    write_utf8_text(conditionMessage(e), output_files$tables$error_log)    message(sprintf("  ERROR: %s", e$message))    return(NULL)  })}
