prepare_overexpression_input <- function(count_mat,                                         selected_genes,                                         target_gene,                                         gene_min_cells,                                         min_cells_after_filter,                                         min_genes_after_filter) {  prepare_knockout_input(    count_mat = count_mat,    selected_genes = selected_genes,    target_gene = target_gene,    gene_min_cells = gene_min_cells,    min_cells_after_filter = min_cells_after_filter,    min_genes_after_filter = min_genes_after_filter  )}
run_scTenifoldOverexpression_safe <- function(countMatrix,                                              gOE,                                              nc_nNet,                                              nc_nCells,                                              ma_nDim,                                              overexpression_factor = 2,                                              seed = 123L,                                              nCores = 1L) {  if (!requireNamespace("scTenifoldNet", quietly = TRUE)) {    stop("Missing scTenifoldNet package; cannot run virtual overexpression workflow.")  }  if (!gOE %in% rownames(countMatrix)) {    stop(sprintf("%s is not in the input expression matrix.", gOE))  }
  set.seed(as.integer(seed))  WT <- scTenifoldNet::makeNetworks(    X = countMatrix,    q = 0.9,    nNet = as.integer(nc_nNet),    nCells = as.integer(nc_nCells),    scaleScores = TRUE,    symmetric = FALSE,    nComp = 3L,    nCores = as.integer(nCores)  )  message(sprintf("  Network construction complete (nNet = %d, nCells per net = %d)",                  as.integer(nc_nNet), as.integer(nc_nCells)))
  WT <- scTenifoldNet::tensorDecomposition(    xList = WT,    K = 3L,    maxError = 1e-05,    maxIter = 1000L,    nDecimal = 3L  )  message("  Tensor decomposition completed (K = 3)")
  WT <- strict_direction_fn(WT$X, lambda = 0)  WT <- as.matrix(WT)  diag(WT) <- 0  WT <- t(WT)  message("  Prepared WT adjacency matrix for overexpression simulation")
  OE <- WT  target_edges <- OE[gOE, ]  positive_edges <- is.finite(target_edges) & target_edges > 0  if (!any(positive_edges)) {    incoming_edges <- WT[, gOE]    positive_edges <- is.finite(incoming_edges) & incoming_edges > 0    if (!any(positive_edges)) {      expr_log <- log1p(countMatrix)      target_expr <- as.numeric(expr_log[gOE, ])      cor_scores <- apply(expr_log, 1, function(x) {        suppressWarnings(stats::cor(as.numeric(x), target_expr, method = "spearman"))      })      cor_scores[gOE] <- NA_real_      cor_scores <- abs(cor_scores)      candidate_genes <- names(sort(cor_scores[is.finite(cor_scores) & cor_scores > 0], decreasing = TRUE))      candidate_genes <- head(candidate_genes[candidate_genes %in% colnames(OE)], 50)      if (length(candidate_genes) == 0) {        stop(sprintf("Gene %s has no network edges and no correlated genes for virtual overexpression.", gOE))      }      global_positive_edges <- WT[is.finite(WT) & WT > 0]      base_weight <- if (length(global_positive_edges) > 0) {        as.numeric(stats::quantile(global_positive_edges, 0.75, na.rm = TRUE))      } else {        1      }      if (!is.finite(base_weight) || base_weight <= 0) {        base_weight <- 1      }      target_edges <- rep(0, ncol(OE))      names(target_edges) <- colnames(OE)      scaled_cor <- cor_scores[candidate_genes] / max(cor_scores[candidate_genes], na.rm = TRUE)      target_edges[candidate_genes] <- base_weight * pmax(scaled_cor, 0.1)      positive_edges <- colnames(OE) %in% candidate_genes      message(sprintf("  Gene %s has no positive network edges; using top correlated genes as de novo OE candidates", gOE))    } else {      target_edges <- incoming_edges      message(sprintf("  Gene %s has no positive outgoing edges; using positive incoming edges as OE candidates", gOE))    }  }
  factor_use <- suppressWarnings(as.numeric(overexpression_factor[1]))  if (!is.finite(factor_use) || is.na(factor_use) || factor_use <= 1) {    factor_use <- 2  }  OE[gOE, positive_edges] <- target_edges[positive_edges] * factor_use  diag(OE) <- 0  message(sprintf("  Simulated %.2fx virtual overexpression for %s", factor_use, gOE))
  MA <- safe_manifold_alignment(    X = WT,    Y = OE,    d = as.integer(ma_nDim),    nCores = as.integer(nCores)  )  message(sprintf("  Manifold alignment completed (d = %d)", attr(MA, "aligned_d")))
  DR <- dregulation_fn(MA, gOE)  message(sprintf("  Differential regulation computed for %s overexpression", gOE))
  list(    tensorNetworks = list(WT = Matrix::Matrix(WT), OE = Matrix::Matrix(OE)),    manifoldAlignment = MA,    diffRegulation = DR  )}
get_overexpression_output_files <- function(gene_output_dir, overexpression_gene) {  list(    tables = list(      runtime_config = file.path(gene_output_dir, "00_Overexpression_Runtime_Config.txt"),      summary = file.path(gene_output_dir, "01_Overexpression_Summary.csv"),      all_results = file.path(gene_output_dir, "02_Overexpression_All_Results.csv"),      significant_results = file.path(gene_output_dir, "03_Overexpression_Significant_Results.csv"),      error_log = file.path(gene_output_dir, "06_Overexpression_Error.txt")    ),    plots = list(      scatter = file.path(gene_output_dir, "04_Overexpression_Scatter.pdf"),      barplot = file.path(gene_output_dir, "05_Overexpression_Barplot.pdf")    ),    legacy = list(      significant = file.path(gene_output_dir, paste0(overexpression_gene, "_OE_sigDiff.csv")),      all = file.path(gene_output_dir, paste0(overexpression_gene, "_OE_allResults.csv")),      summary = file.path(gene_output_dir, paste0(overexpression_gene, "_OE_summary.csv")),      scatter = file.path(gene_output_dir, paste0(overexpression_gene, "_OE_scatter.pdf")),      barplot = file.path(gene_output_dir, paste0(overexpression_gene, "_OE_barplot.pdf"))    )  )}
get_overexpression_run_output_files <- function(output_dir) {  list(    runtime_config = file.path(output_dir, "00_Overexpression_Runtime_Config.txt"),    celltype_distribution = file.path(output_dir, "01_CellType_Distribution.csv"),    gene_availability = file.path(output_dir, "02_Overexpression_Gene_Availability.csv"),    run_summary = file.path(output_dir, "03_Overexpression_Summary.csv"),    result_metadata = file.path(output_dir, "04_Overexpression_Metadata.csv"),    legacy_summary = file.path(output_dir, "All_Overexpression_Analysis_Summary.csv")  )}
run_disease_overexpression_analysis <- function(seurat_obj,                                                overexpression_gene,                                                output_dir,                                                params,                                                n_cores = NULL) {  message(sprintf("\n--- Analyzing %s virtual overexpression in all Disease cells ---", overexpression_gene))
  gene_output_dir <- file.path(output_dir, paste0("Gene_", overexpression_gene))  dir.create(gene_output_dir, recursive = TRUE, showWarnings = FALSE)  output_files <- get_overexpression_output_files(gene_output_dir, overexpression_gene)
  tryCatch({    n_cells <- ncol(seurat_obj)    disease_celltypes <- sort(unique(as.character(Idents(seurat_obj))))    message(sprintf("  Using %d Disease cells", n_cells))
    assay_name <- tryCatch(as.character(Seurat::DefaultAssay(seurat_obj)), error = function(e) "RNA")    count_matrix_full <- get_count_matrix(seurat_obj, assay_name = assay_name)
    if (!(overexpression_gene %in% rownames(count_matrix_full))) {      stop(sprintf("Gene %s is not in the counts matrix.", overexpression_gene))    }
    oe_gene_expr <- sum(count_matrix_full[overexpression_gene, ])    oe_gene_cells <- sum(count_matrix_full[overexpression_gene, ] > 0)    oe_gene_pct <- oe_gene_cells / ncol(count_matrix_full) * 100    message(sprintf("  Overexpression gene %s: total counts=%.0f, expressed in %.0f cells (%.1f%%)",                    overexpression_gene, oe_gene_expr, oe_gene_cells, oe_gene_pct))
    hvg_features <- VariableFeatures(seurat_obj)    if (length(hvg_features) == 0) {      detected_cells_per_gene <- Matrix::rowSums(count_matrix_full > 0)      hvg_features <- names(sort(detected_cells_per_gene, decreasing = TRUE))      message("  WARNING: Variable genes unavailable, fallback to genes ranked by detected cell count")    }
    selected_features <- unique(c(overexpression_gene, hvg_features))    selected_features <- selected_features[selected_features %in% rownames(count_matrix_full)]
    prepared_input <- prepare_overexpression_input(      count_mat = count_matrix_full,      selected_genes = selected_features,      target_gene = overexpression_gene,      gene_min_cells = params$gene_min_cells,      min_cells_after_filter = params$min_cells_after_filter,      min_genes_after_filter = params$min_genes_after_filter    )    expr_df <- prepared_input$matrix
    message(sprintf("  Expression matrix: %d genes x %d cells", nrow(expr_df), ncol(expr_df)))    message("  Running scTenifoldNet virtual overexpression analysis...")
    n_cells_for_net <- min(as.integer(params$nc_nCells), ncol(expr_df))    n_cores_use <- suppressWarnings(as.integer(if (is.null(n_cores)) 1L else n_cores[1]))    if (!is.finite(n_cores_use) || is.na(n_cores_use) || n_cores_use < 1L) {      n_cores_use <- 1L    }
    oe_result <- run_scTenifoldOverexpression_safe(      countMatrix = expr_df,      gOE = overexpression_gene,      nc_nNet = as.integer(params$nc_nNet),      nc_nCells = n_cells_for_net,      ma_nDim = as.integer(params$ma_nDim),      overexpression_factor = params$overexpression_factor,      seed = params$seed,      nCores = n_cores_use    )
    if (is.null(oe_result$diffRegulation)) {      stop("scTenifoldNet virtual overexpression returned no differential regulation result.")    }
    diff_reg_genes <- as.data.frame(oe_result$diffRegulation, stringsAsFactors = FALSE)    if (nrow(diff_reg_genes) == 0) {      stop("scTenifoldNet virtual overexpression returned no result rows.")    }    required_cols <- c("gene", "FC")    missing_cols <- setdiff(required_cols, colnames(diff_reg_genes))    if (length(missing_cols) > 0) {      stop(sprintf("Overexpression results missing required columns: %s", paste(missing_cols, collapse = ", ")))    }
    if (!"p.adj" %in% colnames(diff_reg_genes)) {      if ("p.value" %in% colnames(diff_reg_genes)) {        diff_reg_genes$p.adj <- diff_reg_genes$p.value      } else {        stop("Overexpression results missing p.adj / p.value columns.")      }    }    if (!"p.value" %in% colnames(diff_reg_genes)) {      diff_reg_genes$p.value <- diff_reg_genes$p.adj    }    if (!"Z" %in% colnames(diff_reg_genes)) {      diff_reg_genes$Z <- NA_real_    }
    numeric_cols <- intersect(c("distance", "Z", "FC", "p.value", "p.adj"), colnames(diff_reg_genes))    for (col in numeric_cols) {      diff_reg_genes[[col]] <- as.numeric(diff_reg_genes[[col]])    }
    diff_reg_genes <- diff_reg_genes %>%      dplyr::filter(gene != overexpression_gene) %>%      dplyr::mutate(        log_p.adj = -log10(pmax(p.adj, .Machine$double.xmin)),        significant = ifelse(p.adj < params$pval_threshold, "Significant", "Not significant")      ) %>%      dplyr::arrange(p.adj, dplyr::desc(abs(FC)))
    sig_diff_genes <- diff_reg_genes %>% dplyr::filter(p.adj < params$pval_threshold)
    message(sprintf("  Found %d differentially regulated genes", nrow(diff_reg_genes)))    message(sprintf("  Significant genes: %d (p.adj < %.3f)", nrow(sig_diff_genes), params$pval_threshold))
    oe_summary <- data.frame(      Gene = overexpression_gene,      Cells_Used = prepared_input$cells_used,      Genes_Used = prepared_input$genes_used,      Overexpression_Factor = as.numeric(params$overexpression_factor),      Significant_Genes = nrow(sig_diff_genes),      Top_Hit_Gene = if (nrow(diff_reg_genes) > 0) diff_reg_genes$gene[1] else NA_character_,      Top_Hit_FDR = if (nrow(diff_reg_genes) > 0) diff_reg_genes$p.adj[1] else NA_real_,      stringsAsFactors = FALSE    )
    oe_metadata <- data.frame(      Gene = overexpression_gene,      Group = "Disease",      Disease_Cells = n_cells,      Network_Cells_Used = n_cells_for_net,      Cell_Types = paste(disease_celltypes, collapse = "; "),      Overexpression_Factor = as.numeric(params$overexpression_factor),      Overexpression_Gene_Total_Counts = as.numeric(oe_gene_expr),      Overexpression_Gene_Expressed_Cells = as.numeric(oe_gene_cells),      Overexpression_Gene_Expression_Pct = round(oe_gene_pct, 3),      stringsAsFactors = FALSE    )
    runtime_lines <- c(      paste0("Overexpression_Gene: ", overexpression_gene),      "Group: Disease",      paste0("Disease_Cells: ", n_cells),      paste0("Disease_Cell_Types: ", paste(disease_celltypes, collapse = ", ")),      paste0("Overexpression_Factor: ", params$overexpression_factor),      paste0("Overexpression_Gene_Total_Counts: ", format(round(oe_gene_expr, 0), scientific = FALSE, trim = TRUE)),      paste0("Overexpression_Gene_Expressed_Cells: ", format(round(oe_gene_cells, 0), scientific = FALSE, trim = TRUE)),      paste0("Overexpression_Gene_Expression_Pct: ", round(oe_gene_pct, 3)),      paste0("Cells_Used: ", prepared_input$cells_used),      paste0("Genes_Used: ", prepared_input$genes_used),      paste0("Network_Cells_Used: ", n_cells_for_net),      paste0("ma_nDim: ", params$ma_nDim),      paste0("n_cores: ", n_cores_use),      paste0("pval_threshold: ", params$pval_threshold)    )
    write_utf8_text(runtime_lines, output_files$tables$runtime_config)    write_utf8_csv(oe_summary, output_files$tables$summary, row.names = FALSE)    write_utf8_csv(diff_reg_genes, output_files$tables$all_results, row.names = FALSE)    write_utf8_csv(sig_diff_genes, output_files$tables$significant_results, row.names = FALSE)
    if (isTRUE(params$write_legacy_outputs)) {      write_utf8_csv(sig_diff_genes, output_files$legacy$significant, row.names = FALSE)      write_utf8_csv(diff_reg_genes, output_files$legacy$all, row.names = FALSE)      write_utf8_csv(oe_summary, output_files$legacy$summary, row.names = FALSE)    }
    valid_log_padj <- diff_reg_genes$log_p.adj[is.finite(diff_reg_genes$log_p.adj)]    y_upper <- 1    if (length(valid_log_padj) > 0) {      y_upper <- as.numeric(stats::quantile(valid_log_padj, 0.999, na.rm = TRUE))      if (!is.finite(y_upper) || y_upper <= 0) {        y_upper <- max(valid_log_padj)      }    }    if (!is.finite(y_upper) || y_upper <= 0) {      y_upper <- 1    }
    label_genes <- head(sig_diff_genes, 30)    scatter_colors <- c("Significant" = brewer.pal(8, "Set2")[1], "Not significant" = "gray70")    p_scatter <- ggplot(diff_reg_genes, aes(x = Z, y = log_p.adj, color = significant)) +      geom_point(alpha = 0.7, size = 1.5) +      geom_hline(yintercept = -log10(params$pval_threshold), linetype = "dashed", color = scatter_colors["Significant"]) +      scale_color_manual(values = scatter_colors) +      coord_cartesian(ylim = c(0, y_upper)) +      labs(title = paste0(overexpression_gene, " Overexpression"), x = "Z-score", y = "-log10(p.adj)") +      theme_classic(base_size = 14) +      theme(plot.title = element_text(hjust = 0.5, face = "bold", size = 16), axis.title = element_text(size = 14, face = "bold"), axis.text = element_text(size = 12), legend.position = "none")
    if (nrow(label_genes) > 0) {      p_scatter <- p_scatter + ggrepel::geom_text_repel(data = label_genes, aes(label = gene), size = 3, max.overlaps = 50, color = "black", fontface = "italic")    }
    pdf(output_files$plots$scatter, width = 6, height = 5)    print(p_scatter)    dev.off()    if (isTRUE(params$write_legacy_outputs)) {      file.copy(output_files$plots$scatter, output_files$legacy$scatter, overwrite = TRUE)    }
    top_genes <- head(diff_reg_genes[order(-abs(diff_reg_genes$FC), diff_reg_genes$p.adj), , drop = FALSE], 20)    if (nrow(top_genes) > 0) {      bar_colors <- colorRampPalette(brewer.pal(12, "Set3"))(nrow(top_genes))      p_bar <- ggplot(top_genes, aes(x = reorder(gene, FC), y = FC, fill = reorder(gene, FC))) +        geom_col(alpha = 0.9) +        coord_flip() +        scale_fill_manual(values = bar_colors) +        labs(title = paste0("Top 20 Differentially Regulated Genes\n(", overexpression_gene, " Overexpression)"), x = "Gene", y = "FC") +        theme_classic(base_size = 14) +        theme(plot.title = element_text(hjust = 0.5, face = "bold", size = 14), axis.title = element_text(size = 13, face = "bold"), axis.text.y = element_text(size = 11, face = "italic"), axis.text.x = element_text(size = 11), legend.position = "none")
      pdf(output_files$plots$barplot, width = 6, height = 5)      print(p_bar)      dev.off()      if (isTRUE(params$write_legacy_outputs)) {        file.copy(output_files$plots$barplot, output_files$legacy$barplot, overwrite = TRUE)      }    }
    message(sprintf("  Overexpression results saved for %s", overexpression_gene))    return(list(summary = oe_summary, metadata = oe_metadata, diff_genes = diff_reg_genes, group = "Disease", gene = overexpression_gene))  }, error = function(e) {    if (dev.cur() > 1) {      dev.off()    }    write_utf8_text(conditionMessage(e), output_files$tables$error_log)    message(sprintf("  ERROR: %s", e$message))    return(NULL)  })}
available_overexpression_genes <- overexpression_params$overexpression_genes[  overexpression_params$overexpression_genes %in% rownames(scObject_disease_ko)]missing_overexpression_genes <- setdiff(overexpression_params$overexpression_genes, available_overexpression_genes)
if (length(missing_overexpression_genes) > 0) {  message(sprintf("\nWARNING: The following genes not found in data: %s", paste(missing_overexpression_genes, collapse = ", ")))}
overexpression_run_output_files <- get_overexpression_run_output_files(overexpression_output_dir)all_overexpression_results <- list()all_overexpression_summaries <- data.frame()all_overexpression_metadata <- data.frame()
overexpression_gene_availability <- data.frame(  Overexpression_Gene = overexpression_params$overexpression_genes,  Status = ifelse(overexpression_params$overexpression_genes %in% available_overexpression_genes, "Available", "Missing"),  stringsAsFactors = FALSE)
overexpression_celltype_distribution <- as.data.frame(table(scObject_disease_ko$cell_type), stringsAsFactors = FALSE)colnames(overexpression_celltype_distribution) <- c("Cell_Type", "Cell_Count")overexpression_celltype_distribution <- overexpression_celltype_distribution[order(overexpression_celltype_distribution$Cell_Count, decreasing = TRUE), , drop = FALSE]
overexpression_runtime_lines <- c(  "Group: Disease",  paste0("Target_Genes: ", paste(overexpression_params$overexpression_genes, collapse = ", ")),  paste0("Disease_Cells: ", n_disease_cells),  paste0("Disease_Cell_Types: ", paste(unique_celltypes_disease, collapse = ", ")),  paste0("Available_Genes: ", paste(available_overexpression_genes, collapse = ", ")),  paste0("Missing_Genes: ", paste(missing_overexpression_genes, collapse = ", ")),  paste0("n_hvg: ", overexpression_params$n_hvg),  paste0("qc_minLSize: ", overexpression_params$qc_minLSize),  paste0("qc_mtThreshold: ", overexpression_params$qc_mtThreshold),  paste0("gene_min_cells: ", overexpression_params$gene_min_cells),  paste0("min_cells_after_filter: ", overexpression_params$min_cells_after_filter),  paste0("min_genes_after_filter: ", overexpression_params$min_genes_after_filter),  paste0("nc_nNet: ", overexpression_params$nc_nNet),  paste0("nc_nCells: ", overexpression_params$nc_nCells),  paste0("ma_nDim: ", overexpression_params$ma_nDim),  paste0("overexpression_factor: ", overexpression_params$overexpression_factor),  paste0("pval_threshold: ", overexpression_params$pval_threshold),  paste0("seed: ", overexpression_params$seed),  paste0("write_legacy_outputs: ", overexpression_params$write_legacy_outputs))
write_utf8_text(overexpression_runtime_lines, overexpression_run_output_files$runtime_config)write_utf8_csv(overexpression_celltype_distribution, overexpression_run_output_files$celltype_distribution, row.names = FALSE)write_utf8_csv(overexpression_gene_availability, overexpression_run_output_files$gene_availability, row.names = FALSE)
if (length(available_overexpression_genes) > 0) {  message(sprintf("\n========================================================"))  message(sprintf("Starting virtual overexpression simulation for %d genes", length(available_overexpression_genes)))  message(sprintf("Analyzing using all %d Disease cells", n_disease_cells))  message(sprintf("========================================================\n"))
      for (gOE in available_overexpression_genes) {
    message(sprintf("\n########## Analyzing Gene Overexpression: %s ##########", gOE))
    result <- run_disease_overexpression_analysis(
      seurat_obj = scObject_disease_ko,
      overexpression_gene = gOE,
      output_dir = overexpression_output_dir,
      params = overexpression_params
    )
    if (!is.null(result)) {      all_overexpression_results[[gOE]] <- result      all_overexpression_summaries <- rbind(all_overexpression_summaries, result$summary)      all_overexpression_metadata <- rbind(all_overexpression_metadata, result$metadata)      message(sprintf("\nGene %s virtual overexpression analysis completed!", gOE))    } else {      all_overexpression_results[[gOE]] <- NULL    }  }
  if (nrow(all_overexpression_summaries) > 0) {    write_utf8_csv(all_overexpression_summaries, overexpression_run_output_files$run_summary, row.names = FALSE)    if (isTRUE(overexpression_params$write_legacy_outputs)) {      write_utf8_csv(all_overexpression_summaries, overexpression_run_output_files$legacy_summary, row.names = FALSE)    }    message(sprintf("\nOverall overexpression summary saved to: %s", overexpression_run_output_files$run_summary))  }
  if (nrow(all_overexpression_metadata) > 0) {    write_utf8_csv(all_overexpression_metadata, overexpression_run_output_files$result_metadata, row.names = FALSE)  }} else {  message("WARNING: No valid overexpression genes found in the data!")}
message("\n================================================================================")message("         Gene virtual overexpression analysis completed.                       ")message("================================================================================")